/**
 * Returns true if any two distinct numbers in `numbers` are closer
 * than the given `threshold`. Uses a sorted‑array approach for O(n log n) time.
 *
 * @param {number[]} numbers  - Array of numeric values.
 * @param {number} threshold  - Minimum allowed distance between any two numbers.
 * @returns {boolean}
 */
const hasCloseElements = (numbers, threshold) => {
  if (!Array.isArray(numbers) || numbers.length < 2) return false;
  if (threshold <= 0) return false; // no distance can be less than or equal to 0

  // Sort numerically to bring close values next to each other
  const sorted = [...numbers].sort((a, b) => a - b);

  // Check only adjacent pairs
  for (let i = 1; i < sorted.length; i++) {
    if (Math.abs(sorted[i] - sorted[i - 1]) < threshold) {
      return true;
    }
  }
  return false;
};
```

