/**
 * Splits a string of nested parentheses into separate balanced groups.
 * Spaces are ignored.
 *
 * @param {string} paren_string - The input string containing parentheses.
 * @returns {string[]} An array of balanced parenthesis groups.
 */
const separateParenGroups = (paren_string) => {
  const result = [];
  let current = [];
  let depth = 0;

  for (const ch of paren_string) {
    if (ch === ' ') continue;          // ignore spaces

    if (ch === '(') {
      depth += 1;
      current.push(ch);
    } else if (ch === ')') {
      depth -= 1;
      current.push(ch);
      if (depth === 0) {
        result.push(current.join(''));
        current = [];
      }
    }
    // any other characters are ignored
  }

  return result;
};
```

