/**
 * Returns the decimal part of a positive floating‑point number.
 *
 * @param {number} number - A positive floating point number.
 * @returns {number} The fractional part (between 0 and 1).
 */
const truncateNumber = (number) => {
  // Basic validation (optional, but helps catch misuse)
  if (typeof number !== 'number' || !isFinite(number)) {
    throw new TypeError('Input must be a finite number');
  }
  if (number < 0) {
    throw new RangeError('Input must be positive');
  }

  // Subtract the integer part to obtain the decimal part
  return number - Math.trunc(number);
};
```

