/**
 * Separate a string of nested parentheses into top‑level groups.
 *
 * @param {string} paren_string - Input string containing parentheses groups.
 * @returns {string[]} Array of balanced parenthesis groups.
 */
const separateParenGroups = (paren_string) => {
  // Remove all whitespace characters.
  const s = paren_string.replace(/\s+/g, '');

  const groups = [];
  let depth = 0;
  let start = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];

    if (ch === '(') {
      // If we are at the outermost level, mark the start of a new group.
      if (depth === 0) start = i;
      depth++;
    } else if (ch === ')') {
      depth--;
      // When depth returns to zero, we have a complete group.
      if (depth === 0) {
        groups.push(s.slice(start, i + 1));
      }
    }
  }

  return groups;
};
```

