/**
 * Separate a string of nested parentheses into individual balanced groups.
 *
 * @param {string} paren_string - The input string containing parentheses and optional spaces.
 * @returns {string[]} An array of strings, each representing a balanced group of parentheses.
 */
const separateParenGroups = (paren_string) => {
  const result = [];
  let current = '';
  let depth = 0;

  for (const ch of paren_string) {
    if (ch === ' ') continue;          // ignore spaces

    if (ch === '(') {
      depth++;
      current += ch;
    } else if (ch === ')') {
      depth--;
      current += ch;

      // When depth returns to zero, we have a complete balanced group
      if (depth === 0) {
        result.push(current);
        current = '';
      }
    }
  }

  return result;
};
```

