/**
 * Calculates the Mean Absolute Deviation (MAD) of an array of numbers.
 *
 * MAD = (1/n) * Σ |xᵢ - μ|
 * where μ is the arithmetic mean of the array.
 *
 * @param {number[]} numbers - Array of numeric values.
 * @returns {number} The mean absolute deviation.
 */
const meanAbsoluteDeviation = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length === 0) return NaN;

  const mean = numbers.reduce((sum, value) => sum + value, 0) / numbers.length;

  return numbers.reduce((sum, value) => sum + Math.abs(value - mean), 0) / numbers.length;
};
```

