/**
 * Calculates the Mean Absolute Deviation (MAD) of an array of numbers.
 *
 * @param {number[]} numbers - The dataset to analyze.
 * @returns {number} The MAD value. Returns 0 for an empty array.
 */
const meanAbsoluteDeviation = (numbers) => {
  const n = numbers.length;
  if (n === 0) return 0;

  const mean = numbers.reduce((sum, val) => sum + val, 0) / n;
  const totalAbsDiff = numbers.reduce((sum, val) => sum + Math.abs(val - mean), 0);

  return totalAbsDiff / n;
};
```

