/**
 * Inserts the given delimiter between every two consecutive elements of the input array.
 *
 * @param {Array} numbers   The array of elements to intersperse.
 * @param {*}    delimeter  The value to insert between elements.
 * @returns {Array} A new array with the delimiter interleaved.
 */
const intersperse = (numbers, delimeter) => {
  if (!Array.isArray(numbers) || numbers.length === 0) return [];

  // If there's only one element, just return a shallow copy.
  if (numbers.length === 1) return [numbers[0]];

  const result = [numbers[0]];
  for (let i = 1; i < numbers.length; i++) {
    result.push(delimeter, numbers[i]);
  }
  return result;
};
