const parseNestedParens = (paren_string) => {
  // Split the input into groups separated by whitespace
  const groups = paren_string.trim().split(/\s+/);

  // For each group compute the maximum nesting depth
  return groups.map(group => {
    let depth = 0;
    let maxDepth = 0;

    for (const ch of group) {
      if (ch === '(') {
        depth++;
        if (depth > maxDepth) maxDepth = depth;
      } else if (ch === ')') {
        depth = Math.max(0, depth - 1); // guard against malformed input
      }
    }

    return maxDepth;
  });
};
