/**
 * Returns a new array containing only the strings that include the given substring.
 *
 * @param {string[]} strings - The array of strings to filter.
 * @param {string} substring - The substring to search for within each string.
 * @returns {string[]} A new array with only the strings that contain the substring.
 */
const filterBySubstring = (strings, substring) => {
  // Guard against non‑array inputs or missing substring
  if (!Array.isArray(strings) || typeof substring !== 'string') {
    return [];
  }

  // Use String.prototype.includes for readability and modern syntax
  return strings.filter(str => typeof str === 'string' && str.includes(substring));
};
