// Helper to check if a string is a palindrome
const isPalindrome = (s) => s === s.split('').reverse().join('');

/**
 * Returns the shortest palindrome that starts with the given string.
 *
 * @param {string} string - The input string.
 * @returns {string} The shortest palindrome beginning with `string`.
 */
const makePalindrome = (string) => {
  if (string === '') return '';

  let suffixStart = 0;
  // Find the earliest index where the suffix is a palindrome
  while (!isPalindrome(string.slice(suffixStart))) {
    suffixStart += 1;
  }

  // Append the reverse of the prefix before the palindromic suffix
  const prefixToReverse = string.slice(0, suffixStart);
  const reversedPrefix = prefixToReverse.split('').reverse().join('');
  return string + reversedPrefix;
};
