// Helper to check if a string is a palindrome
const isPalindrome = (s) => s === s.split('').reverse().join('');

/**
 * Returns the shortest palindrome that starts with the given string.
 *
 * The algorithm finds the longest suffix of the input that is already a palindrome.
 * It then appends the reverse of the prefix that precedes this suffix.
 *
 * @param {string} string - The input string.
 * @returns {string} The shortest palindrome beginning with `string`.
 */
const makePalindrome = (string) => {
  if (!string) return '';

  // Find the smallest index i such that string.slice(i) is a palindrome.
  for (let i = 0; i < string.length; i++) {
    const suffix = string.slice(i);
    if (isPalindrome(suffix)) {
      const prefix = string.slice(0, i);
      return string + prefix.split('').reverse().join('');
    }
  }

  // Fallback (should never be reached because the empty suffix is a palindrome)
  return string + string.split('').reverse().join('');
};
