/**
 * Performs a bitwise XOR on two binary strings.
 *
 * @param {string} a - First binary string (consisting of '0' and '1').
 * @param {string} b - Second binary string (consisting of '0' and '1').
 * @returns {string} The XOR result as a binary string.
 */
const stringXor = (a, b) => {
  const maxLen = Math.max(a.length, b.length);
  let result = '';

  for (let i = 0; i < maxLen; i++) {
    const bitA = a[a.length - 1 - i] || '0';
    const bitB = b[b.length - 1 - i] || '0';
    // XOR the bits and convert back to string
    result = ((bitA === '1') ^ (bitB === '1')).toString() + result;
  }

  return result;
};
```

