/**
 * Returns the longest string in an array.
 * If multiple strings share the maximum length, the first one is returned.
 * If the array is empty or not an array, null is returned.
 *
 * @param {Array<string>} strings - The array of strings to search.
 * @returns {string|null} The longest string or null if the array is empty.
 */
const longest = (strings) => {
  if (!Array.isArray(strings) || strings.length === 0) return null;

  let longestStr = strings[0];
  let maxLen = longestStr.length;

  for (let i = 1; i < strings.length; i++) {
    const s = strings[i];
    if (s.length > maxLen) {
      longestStr = s;
      maxLen = s.length;
    }
  }

  return longestStr;
};
```

