 *
 * @param {string} str - The input string.
 * @returns {number} The count of unique characters (case‑insensitive).
 */
const countDistinctCharacters = (str) => {
  // Convert to a single case to ignore case differences
  const lower = str.toLowerCase();

  // Use a Set to automatically keep only unique characters
  const uniqueChars = new Set();

  for (const ch of lower) {
    uniqueChars.add(ch);
  }

  return uniqueChars.size;
};
