/**
 * Parse a string of musical notes into an array of beat counts.
 *
 * Supported note representations:
 *   - 'o'   → whole note (4 beats)
 *   - 'o|'  → half note (2 beats)
 *   - '.|'  → quarter note (1 beat)
 *
 * @param {string} music_string - The input string containing notes separated by whitespace.
 * @returns {number[]} An array of integers representing the beat duration of each note.
 */
const parseMusic = (music_string) => {
  if (!music_string) return [];

  const noteToBeats = {
    'o': 4,
    'o|': 2,
    '.|': 1,
  };

  return music_string
    .trim()
    .split(/\s+/)
    .map(token => noteToBeats[token] ?? 0); // default to 0 if unknown token
};
```

