/**
 * Counts how many times `substring` occurs in `string`, including overlapping matches.
 *
 * @param {string} string     The string to search within.
 * @param {string} substring  The substring to count.
 * @returns {number}          The number of occurrences (0 if none).
 */
const howManyTimes = (string, substring) => {
  if (!string || !substring) return 0;          // Handles empty string or empty substring

  const subLen = substring.length;
  const strLen = string.length;
  if (subLen > strLen) return 0;

  let count = 0;
  for (let i = 0; i <= strLen - subLen; i++) {
    if (string.slice(i, i + subLen) === substring) {
      count++;
    }
  }
  return count;
};
```

