const sortNumbers = (numbers) => {
  if (!numbers) return '';

  const words = [
    'zero', 'one', 'two', 'three', 'four',
    'five', 'six', 'seven', 'eight', 'nine'
  ];

  // Convert the input string into an array of words
  const arr = numbers.trim().split(/\s+/);

  // Sort numerically by mapping each word to its index
  const sorted = arr
    .map(word => words.indexOf(word))
    .sort((a, b) => a - b)
    .map(index => words[index]);

  return sorted.join(' ');
};
