/**
 * Returns the two numbers that are closest to each other in the given array.
 * The returned pair is sorted in ascending order: [smaller, larger].
 *
 * @param {number[]} numbers - Array of numbers (length ≥ 2).
 * @returns {[number, number]} The closest pair of numbers.
 */
const findClosestElements = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length < 2) {
    throw new Error('Input must be an array with at least two numbers.');
  }

  // Work on a sorted copy to make adjacent comparison efficient.
  const sorted = [...numbers].sort((a, b) => a - b);

  let minDiff = Infinity;
  let closestPair = [sorted[0], sorted[1]];

  for (let i = 1; i < sorted.length; i++) {
    const diff = sorted[i] - sorted[i - 1];
    if (diff < minDiff) {
      minDiff = diff;
      closestPair = [sorted[i - 1], sorted[i]];
    }
  }

  return closestPair;
};
```

