/**
 * Rescales an array of numbers to the unit interval [0, 1].
 *
 * @param {number[]} numbers - Array of at least two numeric values.
 * @returns {number[]} A new array where the smallest value becomes 0 and the largest becomes 1.
 */
const rescaleToUnit = (numbers) => {
  const min = Math.min(...numbers);
  const max = Math.max(...numbers);

  // If all numbers are identical, avoid division by zero.
  if (max === min) {
    return numbers.map(() => 0);
  }

  return numbers.map((x) => (x - min) / (max - min));
};
```

