 * Rescales an array of numbers to the [0, 1] interval.
 *
 * @param {number[]} numbers - Array of at least two numbers.
 * @returns {number[]} A new array where the smallest value becomes 0
 *                     and the largest becomes 1.
 */
const rescaleToUnit = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length < 2) {
    throw new Error('Input must be an array of at least two numbers.');
  }

  // Find min and max using a single pass
  let min = numbers[0];
  let max = numbers[0];
  for (let i = 1; i < numbers.length; i++) {
    const val = numbers[i];
    if (val < min) min = val;
    if (val > max) max = val;
  }

  // Guard against division by zero (all values equal)
  if (max === min) {
    return numbers.map(() => 0);
  }

  const range = max - min;
  return numbers.map((n) => (n - min) / range);
};
