const largestDivisor = (n) => {
  // For n <= 1 there is no proper divisor smaller than n.
  // Return 1 as a sensible default.
  if (n <= 1) return 1;

  // The largest proper divisor cannot be larger than n/2.
  for (let i = Math.floor(n / 2); i >= 1; i--) {
    if (n % i === 0) return i;
  }

  // Fallback – for completeness (should never reach here for n > 1).
  return 1;
};
```

