const factorize = (n) => {
  const factors = [];
  if (n <= 1) return factors;          // 1 or less has no prime factors

  let divisor = 2;
  while (divisor * divisor <= n) {
    while (n % divisor === 0) {
      factors.push(divisor);
      n = n / divisor;
    }
    divisor++;
  }

  if (n > 1) factors.push(n);          // remaining prime factor
  return factors;
};
