/**
 * Returns the prime factorization of a positive integer `n` as an array
 * of prime factors sorted in ascending order. Each prime appears as many
 * times as it divides `n`.
 *
 * @param {number} n - The integer to factorize (must be >= 2).
 * @returns {number[]} An array of prime factors.
 */
const factorize = (n) => {
  const factors = [];
  if (n < 2) return factors; // No prime factors for 0, 1, or negative numbers

  let num = n;
  let divisor = 2;

  // Check divisibility by each integer up to sqrt(num)
  while (divisor * divisor <= num) {
    while (num % divisor === 0) {
      factors.push(divisor);
      num = num / divisor;
    }
    divisor += 1;
  }

  // If num > 1, it is a prime factor larger than sqrt(original n)
  if (num > 1) {
    factors.push(num);
  }

  return factors;
};
```

