 * @returns {number|null} The largest divisor of `n` that is < n, or null if none exists.
 */
const largestDivisor = (n) => {
  if (n <= 1) return null;          // No proper divisor exists

  // The largest possible proper divisor is at most n/2.
  for (let i = Math.floor(n / 2); i >= 1; i--) {
    if (n % i === 0) return i;     // First match is the largest
  }

  // Fallback – should never be reached for n > 1
  return 1;
};
