/**
 * Returns true if the given integer n is a prime number, otherwise false.
 *
 * @param {number} n - The number to test for primality.
 * @returns {boolean} True if n is prime, false otherwise.
 */
const isPrime = (n) => {
  // Handle non‑positive numbers and 1
  if (n <= 1) return false;

  // 2 and 3 are prime
  if (n <= 3) return true;

  // Eliminate even numbers and multiples of 3
  if (n % 2 === 0 || n % 3 === 0) return false;

  // Check divisibility by numbers of the form 6k ± 1 up to sqrt(n)
  const limit = Math.floor(Math.sqrt(n));
  for (let i = 5; i <= limit; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) return false;
  }

  return true;
};
