// Evaluate a polynomial with coefficients xs at point x
const poly = (xs, x) =>
  xs.reduce((sum, coeff, i) => sum + coeff * Math.pow(x, i), 0);

// Find a real root of the polynomial defined by the coefficient list xs
// (xs must contain an even number of coefficients, guaranteeing an odd‑degree polynomial)
const findZero = (xs) => {
  let begin = -1.0;
  let end   =  1.0;

  // Expand the interval until the polynomial values at the ends have opposite signs
  while (poly(xs, begin) * poly(xs, end) > 0) {
    begin *= 2.0;
    end   *= 2.0;
  }

  // Bisection method to refine the root
  while (end - begin > 1e-10) {
    const mid = (begin + end) / 2.0;
    if (poly(xs, mid) * poly(xs, begin) > 0) {
      begin = mid;
    } else {
      end = mid;
    }
  }

  // Return the midpoint of the final interval as the root
  return (begin + end) / 2.0;
};
