// Evaluate a polynomial with coefficients xs at point x
const poly = (xs, x) => xs.reduce((sum, coeff, i) => sum + coeff * Math.pow(x, i), 0);

// Find a real root of a polynomial whose coefficients list has an even length
// (i.e., the polynomial has odd degree and thus at least one real root).
const findZero = (xs) => {
  const f = (x) => poly(xs, x);

  // Initial interval
  let left = -1.0;
  let right = 1.0;

  // If either endpoint is already a root, return it
  if (f(left) === 0) return left;
  if (f(right) === 0) return right;

  // Expand the interval until a sign change occurs
  while (f(left) * f(right) > 0) {
    left *= 2;
    right *= 2;
    // Safety guard against runaway expansion
    if (Math.abs(left) > 1e12 || Math.abs(right) > 1e12) break;
  }

  // Binary search for the root
  const tolerance = 1e-10;
  let iterations = 0;
  const maxIterations = 1000;

  while (Math.abs(left - right) > tolerance && iterations < maxIterations) {
    const mid = (left + right) / 2;
    const fmid = f(mid);

    if (fmid === 0) return mid; // exact root found

    // Decide which sub‑interval contains the root
    if (fmid * f(right) > 0) {
      left = mid;
    } else {
      right = mid;
    }
    iterations++;
  }

  // Return the midpoint of the final interval as the root approximation
  return (left + right) / 2;
};
