/**
 * Returns a new array where elements at indices divisible by 3 are replaced
 * by the sorted values of those elements from the original array.
 *
 * @param {Array<number>} l - The input array.
 * @returns {Array<number>} A new array with the required transformation.
 */
const sortThird = (l) => {
  // Extract indices divisible by 3 and their corresponding values
  const indices = [];
  const values = [];
  for (let i = 0; i < l.length; i++) {
    if (i % 3 === 0) {
      indices.push(i);
      values.push(l[i]);
    }
  }

  // Sort the extracted values in ascending order
  values.sort((a, b) => a - b);

  // Build the result array
  const result = l.slice(); // shallow copy of the original array
  for (let i = 0; i < indices.length; i++) {
    result[indices[i]] = values[i];
  }

  return result;
};
