/**
 * Evaluate a polynomial with coefficients in ascending order.
 * @param {number[]} coeffs - Coefficients [a0, a1, ..., an]
 * @param {number} x - Point at which to evaluate
 * @returns {number} Polynomial value at x
 */
function evaluate(coeffs, x) {
  let result = 0;
  let power = 1; // x^0
  for (let i = 0; i < coeffs.length; i++) {
    result += coeffs[i] * power;
    power *= x;
  }
  return result;
}

/**
 * Find a real root of an odd‑degree polynomial.
 * The input array must contain an even number of coefficients
 * (hence the degree is odd) and the leading coefficient is non‑zero.
 *
 * @param {number[]} xs - Coefficients of the polynomial in ascending order
 * @returns {number} One real root of the polynomial
 */
const findZero = (xs) => {
  // Find a bound where the polynomial changes sign
  let bound = 1.0;
  const f = (x) => evaluate(xs, x);

  // Ensure we have a sign change between -bound and +bound
  while (f(-bound) * f(bound) > 0) {
    bound *= 2;
    // Prevent infinite loop in pathological cases
    if (bound > 1e12) throw new Error('Unable to find sign change');
  }

  let low = -bound;
  let high = bound;
  const eps = 1e-12;

  // Bisection method
  while (high - low > eps) {
    const mid = (low + high) / 2;
    const fm = f(mid);
    if (fm === 0) return mid; // exact root found
    if (f(low) * fm < 0) {
      high = mid;
    } else {
      low = mid;
    }
  }

  return (low + high) / 2;
};
```

