/**
 * Returns a new array where the elements at even indices are sorted,
 * while the elements at odd indices remain unchanged.
 *
 * @param {Array<number>} l - The input array.
 * @returns {Array<number>} A new array with sorted even-indexed values.
 */
const sortEven = (l) => {
  // Extract values at even indices (0, 2, 4, ...) and sort them.
  const sortedEven = l
    .filter((_, idx) => idx % 2 === 0)
    .sort((a, b) => a - b);

  // Reconstruct the array, replacing even indices with sorted values.
  let evenPos = 0;
  return l.map((item, idx) =>
    idx % 2 === 0 ? sortedEven[evenPos++] : item
  );
};
