/**
 * Decodes a string that was encoded with encodeCyclic.
 *
 * encodeCyclic groups the input into chunks of 3 characters and
 * rotates each full chunk left by one position.
 * decodeCyclic reverses that operation by rotating each full chunk
 * right by one position.
 *
 * @param {string} s - The encoded string.
 * @returns {string} The decoded original string.
 */
const decodeCyclic = (s) => {
  const groups = [];
  const groupCount = Math.floor((s.length + 2) / 3);

  // Split the string into groups of up to 3 characters
  for (let i = 0; i < groupCount; i++) {
    const start = 3 * i;
    const end = Math.min(start + 3, s.length);
    groups.push(s.slice(start, end));
  }

  // Reverse the rotation for each full group
  const decodedGroups = groups.map((group) => {
    if (group.length === 3) {
      // Rotate right by one: last char + first two chars
      return group.slice(2) + group.slice(0, 2);
    }
    return group; // leave incomplete groups unchanged
  });

  return decodedGroups.join('');
};
```

