/**
 * Decodes a string that was encoded with the `encode_cyclic` function.
 *
 * The `encode_cyclic` function is assumed to shift each alphabetic
 * character forward by its position index (0‑based) in the string,
 * wrapping around the alphabet (cyclically).  Non‑alphabetic characters
 * are left unchanged.
 *
 * Example:
 *   encode_cyclic("abc")  → "ace"   // a+0, b+1, c+2
 *   decodeCyclic("ace")  → "abc"
 *
 * @param {string} s - The encoded string.
 * @returns {string} The decoded string.
 */
const decodeCyclic = (s) => {
  let result = '';

  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);

    // Handle uppercase letters
    if (code >= 65 && code <= 90) {
      const base = 65;
      const offset = ((code - base - i) % 26 + 26) % 26; // ensure positive
      result += String.fromCharCode(base + offset);
      continue;
    }

    // Handle lowercase letters
    if (code >= 97 && code <= 122) {
      const base = 97;
      const offset = ((code - base - i) % 26 + 26) % 26;
      result += String.fromCharCode(base + offset);
      continue;
    }

    // Non‑alphabetic characters are unchanged
    result += s[i];
  }

  return result;
};
```

