const primeFib = (n) => {
  // Helper to test primality
  const isPrime = (p) => {
    if (p < 2) return false;
    if (p === 2) return true;
    if (p % 2 === 0) return false;
    for (let i = 3; i * i <= p; i += 2) {
      if (p % i === 0) return false;
    }
    return true;
  };

  // Generate Fibonacci numbers and count primes
  let a = 0, b = 1;
  while (true) {
    const next = a + b;
    a = b;
    b = next;
    if (isPrime(next)) {
      n -= 1;
      if (n === 0) return next;
    }
  }
};
