/**
 * Returns the n‑th Fibonacci number that is also prime.
 *
 * @param {number} n - The ordinal position (1‑based) of the desired prime Fibonacci number.
 * @returns {number|bigint} The n‑th prime Fibonacci number. If the value exceeds
 *                          Number.MAX_SAFE_INTEGER it is returned as a BigInt.
 */
const primeFib = (n) => {
  if (n < 1) throw new Error('n must be a positive integer');

  // Helper: primality test for BigInt
  const isPrime = (x) => {
    if (x < 2n) return false;
    if (x === 2n || x === 3n) return true;
    if (x % 2n === 0n || x % 3n === 0n) return false;
    let i = 5n;
    const step = 6n;
    while (i * i <= x) {
      if (x % i === 0n || x % (i + 2n) === 0n) return false;
      i += step;
    }
    return true;
  };

  let a = 0n, b = 1n;          // Fibonacci seeds
  let count = 0;               // number of prime Fibonacci numbers found

  while (true) {
    const next = a + b;        // next Fibonacci number
    a = b;
    b = next;

    if (isPrime(next)) {
      count++;
      if (count === n) {
        // Return as Number if safe, otherwise as BigInt
        return next <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(next) : next;
      }
    }
  }
};
