const triplesSumToZero = (l) => {
  if (!Array.isArray(l) || l.length < 3) return false;

  // Sort the array to enable two‑pointer technique
  const arr = [...l].sort((a, b) => a - b);
  const n = arr.length;

  for (let i = 0; i < n - 2; i++) {
    let left = i + 1;
    let right = n - 1;

    while (left < right) {
      const sum = arr[i] + arr[left] + arr[right];

      if (sum === 0) return true;
      if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
};
