/**
 * Calculates the number of collisions between two sets of cars moving in opposite directions.
 *
 * All cars start far apart, move at the same speed, and continue after each collision.
 * Each left‑to‑right car will meet every right‑to‑left car exactly once, so the total
 * number of collisions is simply n * n.
 *
 * @param {number} n - The number of cars in each direction (must be a non‑negative integer).
 * @returns {number} The total number of collisions.
 */
const carRaceCollision = (n) => {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error('n must be a non‑negative integer');
  }
  return n * n;
};
```

