 * Returns true if any three distinct elements in the array sum to zero.
 * @param {number[]} l - Array of integers.
 * @returns {boolean}
 */
const triplesSumToZero = (l) => {
  const n = l.length;
  if (n < 3) return false;

  // Sort the array to enable the two‑pointer technique.
  const arr = [...l].sort((a, b) => a - b);

  for (let i = 0; i < n - 2; i++) {
    let left = i + 1;
    let right = n - 1;

    while (left < right) {
      const sum = arr[i] + arr[left] + arr[right];

      if (sum === 0) return true;
      if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
};
