/**
 * Computes the n-th element of the Fib4 sequence.
 *
 * The sequence is defined as:
 *   fib4(0) = 0
 *   fib4(1) = 0
 *   fib4(2) = 2
 *   fib4(3) = 0
 *   fib4(n) = fib4(n-1) + fib4(n-2) + fib4(n-3) + fib4(n-4)   for n ≥ 4
 *
 * This implementation uses an iterative approach with constant
 * memory (four variables) and runs in O(n) time.
 *
 * @param {number} n - The index of the desired Fib4 number (non‑negative integer).
 * @returns {number} The n‑th Fib4 number.
 */
const fib4 = (n) => {
  if (n < 0) throw new Error('n must be a non‑negative integer');

  // Base cases
  if (n === 0) return 0;
  if (n === 1) return 0;
  if (n === 2) return 2;
  if (n === 3) return 0;

  // Initialize the last four values
  let a = 0; // fib4(n-4)
  let b = 0; // fib4(n-3)
  let c = 2; // fib4(n-2)
  let d = 0; // fib4(n-1)

  // Compute iteratively up to fib4(n)
  for (let i = 4; i <= n; i++) {
    const next = a + b + c + d; // fib4(i)
    a = b;
    b = c;
    c = d;
    d = next;
  }

  return d; // fib4(n)
};
