/**
 * Returns the median of the numeric values in the array `l`.
 *
 * @param {number[]} l - An array of numbers.
 * @returns {number|null} The median value, or `null` if the array is empty.
 */
const median = (l) => {
  if (!Array.isArray(l) || l.length === 0) return null;

  // Work on a copy to avoid mutating the original array
  const sorted = [...l].sort((a, b) => a - b);
  const len = sorted.length;
  const mid = Math.floor(len / 2);

  // Odd length: middle element
  if (len % 2 === 1) return sorted[mid];

  // Even length: average of the two middle elements
  return (sorted[mid - 1] + sorted[mid]) / 2;
};
```

