/**
 * Compute 2^n modulo p.
 *
 * Uses binary exponentiation with BigInt to avoid overflow
 * and to support very large exponents or moduli.
 *
 * @param {number|bigint} n - exponent (non‑negative integer)
 * @param {number|bigint} p - modulus (positive integer)
 * @returns {number} 2^n mod p (as a Number if it fits in safe integer)
 */
const modp = (n, p) => {
  const exp = BigInt(n);
  const mod = BigInt(p);

  // Handle trivial cases
  if (mod === 1n) return 0;          // 2^n mod 1 is always 0
  if (exp === 0n) return Number(1n % mod); // 2^0 = 1

  let result = 1n;
  let base = 2n % mod;
  let e = exp;

  while (e > 0n) {
    if (e & 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    e >>= 1n;
  }

  // Convert back to Number if safe, otherwise return BigInt
  return result <= BigInt(Number.MAX_SAFE_INTEGER)
    ? Number(result)
    : result;
};
```

