/**
 * Computes 2^n modulo p.
 * Uses BigInt for arbitrary‑size arithmetic and fast modular exponentiation.
 *
 * @param {number|bigint} n - exponent (non‑negative)
 * @param {number|bigint} p - modulus (positive)
 * @returns {number} 2^n mod p as a JavaScript number
 */
const modp = (n, p) => {
  const bigN = BigInt(n);
  const bigP = BigInt(p);

  // 2^n mod 1 is always 0
  if (bigP === 1n) return 0;

  let result = 1n;
  let base = 2n % bigP;
  let exp = bigN;

  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % bigP;
    base = (base * base) % bigP;
    exp >>= 1n;
  }

  return Number(result);
};
```

