/**
 * Compute 2^n modulo p using fast exponentiation.
 * Works with large n and p by leveraging BigInt.
 *
 * @param {number|bigint} n - exponent (non‑negative)
 * @param {number|bigint} p - modulus (positive)
 * @returns {number} 2^n mod p as a JavaScript number
 */
const modp = (n, p) => {
  const bigN = BigInt(n);
  const bigP = BigInt(p);

  // Handle trivial cases
  if (bigP === 1n) return 0;          // any number mod 1 is 0
  if (bigN === 0n) return 1 % Number(bigP); // 2^0 = 1

  let result = 1n;
  let base = 2n % bigP;
  let exp = bigN;

  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % bigP;
    base = (base * base) % bigP;
    exp >>= 1n;
  }

  return Number(result);
};
```

