/**
 * Decodes a string that was encoded with the `encode_shift` function.
 * `encode_shift` shifts each alphabetic character forward by its
 * zero‑based index in the string (wrapping around the alphabet).
 * This function reverses that operation.
 *
 * @param {string} s - The encoded string.
 * @returns {string} The decoded string.
 */
const decodeShift = (s) => {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    const code = c.charCodeAt(0);
    let newCode = code;

    // Lowercase letters
    if (code >= 97 && code <= 122) {
      const shift = i % 26;
      const offset = (code - 97 - shift + 26) % 26;
      newCode = 97 + offset;
    }
    // Uppercase letters
    else if (code >= 65 && code <= 90) {
      const shift = i % 26;
      const offset = (code - 65 - shift + 26) % 26;
      newCode = 65 + offset;
    }

    result += String.fromCharCode(newCode);
  }
  return result;
};
```

