/**
 * Return the n‑th Fibonacci number.
 *
 * The sequence is defined as:
 *   fib(0) = 0
 *   fib(1) = 1
 *   fib(n) = fib(n-1) + fib(n-2)  for n > 1
 *
 * @param {number} n - The position in the Fibonacci sequence (non‑negative integer).
 * @returns {number} The n‑th Fibonacci number.
 */
const fib = (n) => {
  if (n <= 0) return 0;
  if (n === 1) return 1;

  let a = 0; // fib(0)
  let b = 1; // fib(1)

  for (let i = 2; i <= n; i++) {
    const next = a + b;
    a = b;
    b = next;
  }

  return b;
};
