/**
 * Returns true if the array is monotonically increasing or decreasing.
 * An array with 0 or 1 element is considered monotonic.
 *
 * @param {Array<number>} l - The array to test.
 * @returns {boolean} True if monotonic, otherwise false.
 */
const monotonic = (l) => {
  if (l.length <= 1) return true;

  let increasing = true;
  let decreasing = true;

  for (let i = 1; i < l.length; i++) {
    if (l[i] > l[i - 1]) decreasing = false; // violates decreasing
    if (l[i] < l[i - 1]) increasing = false; // violates increasing
  }

  return increasing || decreasing;
};
