/**
 * Returns true if the array is monotonically increasing or decreasing.
 * Monotonic means non‑decreasing or non‑increasing (adjacent equal values are allowed).
 *
 * @param {Array<Number>} l - The array to test.
 * @returns {boolean} true if l is monotonic, false otherwise.
 */
const monotonic = (l) => {
  if (!Array.isArray(l) || l.length <= 1) return true;

  let increasing = true;
  let decreasing = true;

  for (let i = 1; i < l.length; i++) {
    if (l[i] < l[i - 1]) increasing = false;
    if (l[i] > l[i - 1]) decreasing = false;
    // Early exit if neither direction is possible
    if (!increasing && !decreasing) return false;
  }

  return increasing || decreasing;
};
```

