/**
 * Returns true if the array is monotonically increasing or decreasing.
 * Monotonicity allows equal consecutive elements (non‑decreasing or non‑increasing).
 *
 * @param {Array<number>} l - The array to test.
 * @returns {boolean}
 */
const monotonic = (l) => {
  if (!Array.isArray(l) || l.length <= 1) return true;

  let direction = 0; // 0 = unknown, 1 = increasing, -1 = decreasing

  for (let i = 1; i < l.length; i++) {
    const diff = l[i] - l[i - 1];

    if (diff === 0) continue; // equal elements don't change direction

    const currentDir = diff > 0 ? 1 : -1;

    if (direction === 0) {
      direction = currentDir; // first non‑zero difference sets direction
    } else if (direction !== currentDir) {
      return false; // direction changed → not monotonic
    }
  }

  return true;
};
```

