/**
 * Return a sorted array of the unique elements that appear in both input lists.
 *
 * @param {Array<*>} l1 - First list of values.
 * @param {Array<*>} l2 - Second list of values.
 * @returns {Array<*>} Sorted array of common elements.
 */
const common = (l1, l2) => {
  // Create a set from the first list for O(1) look‑ups.
  const set1 = new Set(l1);

  // Collect common elements in a result set to guarantee uniqueness.
  const result = new Set();
  for (const value of l2) {
    if (set1.has(value)) {
      result.add(value);
    }
  }

  // Convert to an array and sort numerically (or lexicographically if not numbers).
  return [...result].sort((a, b) => (a > b ? 1 : a < b ? -1 : 0));
};
```

