/**
 * Returns the largest prime factor of a given integer n (n > 1 and not prime).
 *
 * @param {number} n - The integer to factorize.
 * @returns {number} The largest prime factor of n.
 */
const largestPrimeFactor = (n) => {
  if (n <= 1) throw new Error('n must be greater than 1');

  let largest = 1;

  // Remove factor 2
  while (n % 2 === 0) {
    largest = 2;
    n /= 2;
  }

  // Check odd factors from 3 upwards
  for (let i = 3; i * i <= n; i += 2) {
    while (n % i === 0) {
      largest = i;
      n /= i;
    }
  }

  // If remaining n is a prime greater than 2
  if (n > 2) {
    largest = n;
  }

  return largest;
};
```

