/**
 * Computes the n-th element of the FibFib sequence.
 *
 * The sequence is defined as:
 *   fibfib(0) = 0
 *   fibfib(1) = 0
 *   fibfib(2) = 1
 *   fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3)   for n >= 3
 *
 * This implementation uses an iterative approach with O(n) time
 * and O(1) additional space.
 *
 * @param {number} n - The index of the desired FibFib number (n >= 0).
 * @returns {number} The n-th FibFib number.
 */
const fibfib = (n) => {
  if (n < 0) throw new Error('n must be a non‑negative integer');

  // Base cases
  if (n === 0 || n === 1) return 0;
  if (n === 2) return 1;

  // Keep only the last three values to save memory
  let a = 0; // fibfib(n-3)
  let b = 0; // fibfib(n-2)
  let c = 1; // fibfib(n-1)

  for (let i = 3; i <= n; i++) {
    const next = a + b + c; // fibfib(i)
    a = b; // shift window
    b = c;
    c = next;
  }

  return c;
};
```

