/**
 * Calculates the number of mangoes in a basket.
 *
 * @param {string} s - A string containing the counts of apples and oranges,
 *                     e.g. "5 apples and 6 oranges".
 * @param {number} n - The total number of fruits in the basket.
 * @returns {number} The number of mangoes.
 */
const fruitDistribution = (s, n) => {
  // Extract all integer numbers from the string
  const numbers = s.match(/\d+/g) || [];
  // Sum the extracted numbers (apples + oranges)
  const sum = numbers.reduce((acc, val) => acc + Number(val), 0);
  // Mangoes are the remaining fruits
  return n - sum;
};
```

