/**
 * Calculates the number of mangoes in a basket.
 *
 * @param {string} s - A string describing the number of apples and oranges,
 *                     e.g., "5 apples and 6 oranges".
 * @param {number} n - The total number of fruits in the basket.
 * @returns {number} The number of mangoes.
 */
const fruitDistribution = (s, n) => {
  // Extract the numbers of apples and oranges using a regular expression.
  const match = s.match(/(\d+)\s*apples\s+and\s+(\d+)\s*oranges/i);
  if (!match) {
    throw new Error('Input string format is invalid.');
  }

  const apples = Number(match[1]);
  const oranges = Number(match[2]);

  // Compute and return the number of mangoes.
  return n - apples - oranges;
};
