/**
 * Returns the smallest even value in the array along with its index.
 * If multiple even values are equal, the first (smallest index) is chosen.
 * If no even values exist or the array is empty, an empty array is returned.
 *
 * @param {number[]} arr - Array of non‑negative integers.
 * @returns {[number, number] | []} - [smallestEvenValue, index] or [].
 */
const pluck = (arr) => {
  if (!arr || arr.length === 0) return [];

  let minEven = Infinity;
  let minIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    const val = arr[i];
    if (val % 2 === 0) {
      if (val < minEven) {
        minEven = val;
        minIndex = i;
      }
    }
  }

  return minIndex === -1 ? [] : [minEven, minIndex];
};
