  const maxVal = Math.max(...lst);
  const freq = new Array(maxVal + 1).fill(0);

  for (const num of lst) {
    if (num > 0) freq[num] += 1;
  }

  let ans = -1;
  for (let i = 1; i <= maxVal; i++) {
    if (freq[i] >= i) ans = i;
  }

  return ans;
};
