/**
 * Returns a new array sorted in a "strange" order:
 * start with the smallest element, then the largest of the remaining,
 * then the next smallest, then the next largest, and so on.
 *
 * @param {number[]} lst - The input array of integers.
 * @returns {number[]} A new array containing the elements in strange order.
 */
const strangeSortList = (lst) => {
  if (!Array.isArray(lst) || lst.length === 0) return [];

  // Work on a sorted copy to avoid mutating the original array.
  const sorted = [...lst].sort((a, b) => a - b);

  const result = [];
  let left = 0;
  let right = sorted.length - 1;

  while (left <= right) {
    result.push(sorted[left++]);          // smallest remaining
    if (left <= right) result.push(sorted[right--]); // largest remaining
  }

  return result;
};
```

