/**
 * Returns the greatest integer > 0 that appears in `lst` at least as many times
 * as its own value. If no such integer exists, returns -1.
 *
 * @param {number[]} lst - Non‑empty array of positive integers.
 * @returns {number}
 */
const search = (lst) => {
  // Build a frequency map
  const freq = new Map();
  for (const n of lst) {
    freq.set(n, (freq.get(n) ?? 0) + 1);
  }

  // Check candidates in descending order
  const candidates = Array.from(freq.keys()).sort((a, b) => b - a);
  for (const val of candidates) {
    if (freq.get(val) >= val) {
      return val;
    }
  }

  // No value satisfies the condition
  return -1;
};
```

