/**
 * Calculates the area of a triangle given its three side lengths.
 * Returns the area rounded to two decimal places if the sides form a valid triangle,
 * otherwise returns -1.
 *
 * @param {number} a - Length of side a
 * @param {number} b - Length of side b
 * @param {number} c - Length of side c
 * @returns {number} The area rounded to 2 decimal places, or -1 if invalid
 */
const triangleArea = (a, b, c) => {
  // Validate that all sides are positive numbers
  if (a <= 0 || b <= 0 || c <= 0) return -1;

  // Triangle inequality check
  if (a + b <= c || a + c <= b || b + c <= a) return -1;

  // Heron's formula: s is the semi‑perimeter
  const s = (a + b + c) / 2;
  const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));

  // Round to two decimal places and return as a number
  return Number(area.toFixed(2));
};
```

