/**
 * Returns a list sorted in a “strange” order:
 *   min, max, next min, next max, …
 *
 * @param {number[]} lst - The input array of integers.
 * @returns {number[]} A new array containing the elements of `lst`
 *                     arranged in the strange order.
 */
const strangeSortList = (lst) => {
  // Work on a copy so the original array is not mutated.
  const sorted = [...lst].sort((a, b) => a - b);

  const result = [];
  let left = 0;                 // index of the current minimum
  let right = sorted.length - 1; // index of the current maximum
  let takeMin = true;           // flag to alternate between min and max

  while (left <= right) {
    if (takeMin) {
      result.push(sorted[left++]); // take the smallest remaining
    } else {
      result.push(sorted[right--]); // take the largest remaining
    }
    takeMin = !takeMin; // flip the flag for the next iteration
  }

  return result;
};
```

