/**
 * Returns true if the array `q` is palindromic (balanced) and its sum
 * of elements is less than or equal to the maximum weight `w`.
 *
 * @param {number[]} q - The array of numbers to evaluate.
 * @param {number} w - The maximum allowed weight.
 * @returns {boolean} - Whether the object will fly.
 */
const willItFly = (q, w) => {
  // Helper to check if an array is a palindrome
  const isPalindrome = (arr) => {
    const len = arr.length;
    for (let i = 0; i < len / 2; i++) {
      if (arr[i] !== arr[len - 1 - i]) return false;
    }
    return true;
  };

  const sum = q.reduce((acc, val) => acc + val, 0);
  return isPalindrome(q) && sum <= w;
};
```

