/**
 * Returns the minimum number of elements that must be changed
 * to make the array palindromic.
 *
 * @param {number[]} arr - The input array of integers.
 * @returns {number} The minimal number of changes required.
 */
const smallestChange = (arr) => {
  let changes = 0;
  const n = arr.length;
  for (let i = 0; i < Math.floor(n / 2); i++) {
    if (arr[i] !== arr[n - 1 - i]) {
      changes++;
    }
  }
  return changes;
};
