// Returns true if `a` is the product of exactly three prime numbers (repetitions allowed).
const isMultiplyPrime = (a) => {
  if (a < 2) return false;

  // Helper: check if a number is prime.
  const isPrime = (n) => {
    if (n < 2) return false;
    for (let i = 2; i * i <= n; i++) {
      if (n % i === 0) return false;
    }
    return true;
  };

  // Generate all primes up to 100 (the maximum possible factor for a < 100).
  const primes = [];
  for (let i = 2; i <= 100; i++) {
    if (isPrime(i)) primes.push(i);
  }

  let count = 0;
  let remaining = a;

  for (const p of primes) {
    while (remaining % p === 0) {
      count++;
      remaining /= p;
      if (count > 3) return false; // early exit
    }
    if (remaining === 1) break;
  }

  // If there's a remaining factor > 1, it's a prime > 100 (impossible for a < 100),
  // but we handle it just in case.
  if (remaining > 1) count++;

  return count === 3;
};
```

