/**
 * Returns true if `x` is a simple power of `n` (i.e. ∃ integer k such that n**k === x).
 * Handles positive, negative, and special cases for n = 0, 1, -1.
 *
 * @param {number} x - The target value.
 * @param {number} n - The base.
 * @returns {boolean}
 */
const isSimplePower = (x, n) => {
  // Handle the trivial cases first
  if (n === 1) return x === 1;          // 1^k = 1 for any k
  if (n === -1) return x === 1 || x === -1; // (-1)^even = 1, odd = -1
  if (n === 0) return x === 0;          // 0^k = 0 for k > 0 (0^0 is undefined)

  // If x is 1, it is always a power (k = 0) unless n is 0 (handled above)
  if (x === 1) return true;

  // If x is negative and n is positive, impossible
  if (x < 0 && n > 0) return false;

  // Use repeated multiplication to find the power
  let power = 1;
  while (true) {
    if (power === x) return true;

    // Stop if we have exceeded the target (taking sign into account)
    if (
      (n > 1 && power > x) ||
      (n < -1 && Math.abs(power) > Math.abs(x))
    ) {
      break;
    }

    power *= n;
  }

  return false;
};
```

