/**
 * Returns true if `x` is a simple power of `n` (i.e. ∃ integer k such that n**k === x).
 * Handles positive, negative, and zero values for `x` and `n` in a robust way.
 *
 * @param {number} x - The target value.
 * @param {number} n - The base.
 * @returns {boolean} True if `x` is a simple power of `n`, otherwise false.
 */
const isSimplePower = (x, n) => {
  // Special cases
  if (x === 1) return n !== 0;          // 1 = n^0 for any n ≠ 0
  if (n === 1) return x === 1;          // 1^k = 1
  if (n === 0) return x === 0;          // 0^k = 0 for k > 0
  if (n === -1) return x === 1 || x === -1; // (-1)^k alternates between 1 and -1
  if (x === 0) return false;            // 0 cannot be expressed as n^k for n ≠ 0

  // General case: repeatedly divide x by n while divisible
  let current = x;
  while (current % n === 0) {
    current /= n;
  }
  return current === 1;
};
```

