/**
 * Counts how many hexadecimal digits in the input string are prime.
 * Prime hexadecimal digits are: 2, 3, 5, 7, B (11), D (13).
 *
 * @param {string} num - A string containing hexadecimal digits (0‑9, A‑F).
 * @returns {number} The count of prime digits.
 */
const hexKey = (num) => {
  // Set of prime hexadecimal characters for O(1) lookup.
  const primeDigits = new Set(['2', '3', '5', '7', 'B', 'D']);

  let count = 0;
  for (const ch of num) {
    if (primeDigits.has(ch)) {
      count++;
    }
  }
  return count;
};
