/**
 * Count the n‑digit positive integers that start or end with 1.
 *
 * For n = 1: only the number 1 satisfies the condition → 1.
 * For n = 2: 10 numbers start with 1, 9 numbers end with 1, 1 number (11) is counted twice → 18.
 * For n ≥ 3: the count simplifies to 18 × 10^(n‑2).
 *
 * The function returns a BigInt to avoid overflow for large n.
 *
 * @param {number} n - The number of digits (must be a positive integer).
 * @returns {bigint} The count of n‑digit numbers that start or end with 1.
 */
const startsOneEnds = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('n must be a positive integer');
  }

  if (n === 1) return 1n;
  if (n === 2) return 18n;

  // For n >= 3: 18 * 10^(n-2)
  return 18n * 10n ** BigInt(n - 2);
};
```

