const antiShuffle = (s) => {
  // Split the string into words and whitespace separators
  const parts = s.split(/(\s+)/);

  // Process each part: sort characters if it's a word, otherwise keep as is
  const sortedParts = parts.map(part => {
    // If the part contains only whitespace, return it unchanged
    if (/^\s*$/.test(part)) return part;

    // Sort characters by ASCII value
    return [...part]
      .sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0))
      .join('');
  });

  // Reconstruct the string
  return sortedParts.join('');
};
