/**
 * Returns the derivative of a polynomial represented by its coefficients.
 *
 * @param {number[]} xs - Coefficients of the polynomial, where xs[i] is the coefficient of x^i.
 * @returns {number[]} Coefficients of the derivative polynomial.
 */
const derivative = (xs) => {
  if (!Array.isArray(xs) || xs.length <= 1) return [];

  // xs.slice(1) gives coefficients starting from x^1.
  // For each coefficient at index i-1 (original index i), multiply by i.
  return xs.slice(1).map((coeff, idx) => (idx + 1) * coeff);
};
