/**
 * Find all coordinates of the value `x` in a jagged 2‑D array.
 *
 * @param {Array<Array<*>>} lst - The jagged array to search.
 * @param {*} x - The value to find.
 * @returns {Array<[number, number]>} An array of [row, column] pairs.
 *
 * The result is sorted first by row (ascending) and then by column
 * (descending) within each row.
 */
const getRow = (lst, x) => {
  const result = [];

  for (let row = 0; row < lst.length; row++) {
    const currentRow = lst[row];
    // iterate columns from end to start to get descending order
    for (let col = currentRow.length - 1; col >= 0; col--) {
      if (currentRow[col] === x) {
        result.push([row, col]); // push as an array pair
      }
    }
  }

  return result;
};
