/**
 * Returns an ordered version of the input string.
 * Each word (sequence of non-space characters) is sorted by ASCII value,
 * while spaces are preserved exactly as in the original string.
 *
 * @param {string} s - The input string to process.
 * @returns {string} - The string with each word sorted.
 */
const antiShuffle = (s) => {
  // Split the string into tokens, keeping the separators (spaces)
  const tokens = s.split(/(\s+)/);

  // Process each token: sort non-space tokens, keep spaces unchanged
  return tokens
    .map((token) => {
      // If the token is only whitespace, return it unchanged
      if (/^\s+$/.test(token)) return token;

      // Sort the characters of the token by ASCII value
      return [...token]
        .sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0))
        .join('');
    })
    .join('');
};
```

