/**
 * Find all coordinates of a given value in a jagged 2‑D array.
 *
 * @param {Array<Array<*>>} lst - The nested list (matrix) to search.
 * @param {*} x - The value to find.
 * @returns {Array<[number, number]>} An array of [row, column] pairs.
 */
const getRow = (lst, x) => {
  const coords = [];

  lst.forEach((row, rIdx) => {
    row.forEach((val, cIdx) => {
      if (val === x) {
        coords.push([rIdx, cIdx]);
      }
    });
  });

  coords.sort((a, b) => {
    if (a[0] === b[0]) {
      return b[1] - a[1]; // columns descending within same row
    }
    return a[0] - b[0];   // rows ascending
  });

  return coords;
};
```

