/**
 * Returns a sorted copy of the input array.
 * - If the sum of the first and last elements is odd, sort ascending.
 * - If the sum is even, sort descending.
 * The original array is left untouched.
 *
 * @param {number[]} array - Array of non‑negative integers.
 * @returns {number[]} A new sorted array.
 */
const sortArray = (array) => {
  // Guard against non‑array inputs and trivial cases
  if (!Array.isArray(array) || array.length <= 1) {
    return array.slice();
  }

  const first = array[0];
  const last = array[array.length - 1];
  const sum = first + last;

  // Determine sort order: ascending if sum is odd, descending otherwise
  const ascending = sum % 2 === 1;

  // Return a sorted copy without mutating the original array
  return array.slice().sort((a, b) => (ascending ? a - b : b - a));
};
