/**
 * Returns a sorted copy of the input array.
 * - If the sum of the first and last elements is odd, sort ascending.
 * - If the sum is even, sort descending.
 * The original array is left untouched.
 *
 * @param {number[]} array - Array of non‑negative integers.
 * @returns {number[]} A new sorted array.
 */
const sortArray = (array) => {
  // Create a shallow copy so the original array is not mutated
  const copy = array.slice();

  // No sorting needed for empty or single‑element arrays
  if (copy.length <= 1) return copy;

  const sum = copy[0] + copy[copy.length - 1];

  // Sort ascending if sum is odd, descending if even
  if (sum % 2 === 1) {
    copy.sort((a, b) => a - b);
  } else {
    copy.sort((a, b) => b - a);
  }

  return copy;
};
```

