/**
 * Counts the number of sentences that start with the word "I".
 * Sentences are delimited by '.', '?' or '!'.
 *
 * @param {string} S - The input string containing words and sentences.
 * @returns {number} The count of boredoms (sentences starting with "I").
 */
const isBored = (S) => {
  // Split the string into potential sentences using punctuation delimiters.
  const parts = S.split(/[.!?]/);

  let count = 0;

  for (const part of parts) {
    // Remove leading/trailing whitespace.
    const sentence = part.trim();

    // Skip empty fragments (e.g., trailing punctuation).
    if (!sentence) continue;

    // Check if the sentence starts with the word "I".
    // The regex ensures "I" is a whole word followed by a space or end of string.
    if (/^I(\s|$)/.test(sentence)) {
      count++;
    }
  }

  return count;
};
