/**
 * Counts the number of sentences that start with the word "I".
 * Sentences are delimited by '.', '?' or '!'.
 *
 * @param {string} S - The input string containing words and sentences.
 * @returns {number} The number of boredoms (sentences starting with "I").
 */
const isBored = (S) => {
  let count = 0;
  const delimiterRegex = /[.!?]/g;
  let start = 0;
  let match;

  while ((match = delimiterRegex.exec(S)) !== null) {
    const end = match.index;
    const sentence = S.slice(start, end).trim();

    // Check if the sentence starts with the word "I"
    if (
      sentence.startsWith('I') &&
      // Ensure the next character is not a letter (i.e., the word is exactly "I")
      !/[a-zA-Z]/.test(sentence[1] ?? '')
    ) {
      count++;
    }

    start = end + 1; // Move past the delimiter
  }

  return count;
};
