/**
 * Returns the sum of the digits of the largest prime number in the list.
 * If the list contains no prime numbers, the function returns 0.
 *
 * @param {number[]} lst - Array of integers.
 * @returns {number} Sum of the digits of the largest prime found.
 */
const skjkasdkd = (lst) => {
  // Helper to check primality
  const isPrime = (n) => {
    if (n <= 1) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;
    const limit = Math.floor(Math.sqrt(n));
    for (let i = 3; i <= limit; i += 2) {
      if (n % i === 0) return false;
    }
    return true;
  };

  let maxPrime = -Infinity;

  for (const num of lst) {
    if (isPrime(num) && num > maxPrime) {
      maxPrime = num;
    }
  }

  if (maxPrime === -Infinity) return 0; // no prime found

  // Sum digits of maxPrime
  let sum = 0;
  let temp = Math.abs(maxPrime); // handle negative just in case
  while (temp > 0) {
    sum += temp % 10;
    temp = Math.floor(temp / 10);
  }

  return sum;
};
```

