  const vowels = new Set(['A', 'E', 'I', 'O', 'U']);
  let result = '';

  for (const ch of message) {
    // Preserve spaces (or any non‑letter characters)
    if (ch === ' ') {
      result += ch;
      continue;
    }

    // Swap case
    const swapped = ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase();

    // Replace vowels with the letter 2 places ahead
    if (vowels.has(swapped)) {
      const newCode = swapped.charCodeAt(0) + 2;
      result += String.fromCharCode(newCode);
    } else {
      result += swapped;
    }
  }

  return result;
};
