/**
 * Encode a message by swapping the case of every letter and
 * replacing each vowel with the letter two positions ahead
 * in the alphabet.
 *
 * @param {string} message - The input string containing only letters and spaces.
 * @returns {string} The encoded string.
 */
const encode = (message) => {
  let result = '';

  for (let i = 0; i < message.length; i++) {
    const ch = message[i];
    const code = ch.charCodeAt(0);

    // Skip non‑letters (e.g., spaces)
    if ((code < 65 || code > 90) && (code < 97 || code > 122)) {
      result += ch;
      continue;
    }

    // Swap case
    let swappedCode = code;
    if (code >= 65 && code <= 90) {          // uppercase → lowercase
      swappedCode += 32;
    } else {                                 // lowercase → uppercase
      swappedCode -= 32;
    }

    // Replace vowels (now guaranteed to be lowercase) with +2
    if (
      swappedCode === 97 ||  // a
      swappedCode === 101 || // e
      swappedCode === 105 || // i
      swappedCode === 111 || // o
      swappedCode === 117    // u
    ) {
      swappedCode += 2;
    }

    result += String.fromCharCode(swappedCode);
  }

  return result;
};
```

