 * Checks whether all keys of an object are either all lower‑case or all upper‑case.
 * Returns false if the object is empty or if any key is not a string.
 *
 * @param {Object} dict - The dictionary to check.
 * @returns {boolean} True if all keys are uniformly lower‑case or upper‑case, otherwise false.
 */
const checkDictCase = (dict) => {
  // Empty dictionary → false
  const keys = Object.keys(dict);
  if (keys.length === 0) return false;

  let hasLower = false;
  let hasUpper = false;

  for (const key of keys) {
    // Key must be a string
    if (typeof key !== 'string') return false;

    // Check each character of the key
    for (let i = 0; i < key.length; i++) {
      const code = key.charCodeAt(i);
      if (code >= 65 && code <= 90) hasUpper = true;   // A-Z
      if (code >= 97 && code <= 122) hasLower = true; // a-z
    }
  }

  // If both lower and upper case keys exist, or none exist, return false
  if (hasLower && hasUpper) return false;
  if (!hasLower && !hasUpper) return false; // e.g., keys with no letters

  return true;
};
```

