/**
 * Returns an array of all prime numbers that are strictly less than `n`.
 *
 * @param {number} n - A non‑negative integer.
 * @returns {number[]} An array of primes less than `n`.
 */
const countUpTo = (n) => {
  if (typeof n !== 'number' || n < 0) return [];

  const primes = [];
  for (let i = 2; i < n; i++) {
    if (isPrime(i)) primes.push(i);
  }
  return primes;
};

