 *
 * @param {number} num - The number to test.
 * @returns {boolean} True if `num` is prime, false otherwise.
 */
const isPrime = (num) => {
  if (num < 2) return false;
  for (let d = 2; d * d <= num; d++) {
    if (num % d === 0) return false;
  }
  return true;
};
