const encode = (message) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  let result = '';

  for (const ch of message) {
    // Swap case
    const swapped = ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase();

    // Check if the swapped character is a vowel (case‑insensitive)
    const lower = swapped.toLowerCase();
    if (vowels.has(lower)) {
      // Replace with the letter 2 places ahead
      const replacedCode = lower.charCodeAt(0) + 2;
      let replaced = String.fromCharCode(replacedCode);

      // Preserve the swapped case
      if (swapped === swapped.toUpperCase()) {
        replaced = replaced.toUpperCase();
      }
      result += replaced;
    } else {
      result += swapped;
    }
  }

  return result;
};
