/**
 * Returns the closest integer to the numeric string `value`.
 * If the number is exactly halfway between two integers, it rounds away from zero.
 *
 * @param {string} value - A string representation of a number.
 * @returns {number} The closest integer.
 */
const closestInteger = (value) => {
  const num = Number(value);
  if (Number.isNaN(num)) return NaN; // or throw an error if preferred

  const floor = Math.floor(num);
  const ceil = Math.ceil(num);

  // If the number is already an integer, return it.
  if (floor === ceil) return floor;

  const diffFloor = Math.abs(num - floor);
  const diffCeil = Math.abs(ceil - num);

  if (diffFloor < diffCeil) return floor;
  if (diffCeil < diffFloor) return ceil;

  // Equidistant: round away from zero.
  return num >= 0 ? ceil : floor;
};
```

