/**
 * Returns the integer closest to the given numeric string.
 * If the number is exactly halfway between two integers, the result
 * is the integer that is farther from zero (rounding away from zero).
 *
 * @param {string} value - A string representation of a number.
 * @returns {number} The closest integer.
 */
const closestInteger = (value) => {
  const num = Number(value);
  if (Number.isNaN(num)) return NaN;

  const floor = Math.floor(num);
  const ceil = Math.ceil(num);

  const diffFloor = Math.abs(num - floor);
  const diffCeil = Math.abs(ceil - num);

  if (diffFloor < diffCeil) return floor;
  if (diffCeil < diffFloor) return ceil;

  // Ties: choose the integer farther from zero
  return Math.abs(floor) > Math.abs(ceil) ? floor : ceil;
};
