/**
 * Creates a pile of stones with `n` levels.
 * The first level contains `n` stones.
 * Each subsequent level contains the next odd number if `n` is odd,
 * or the next even number if `n` is even.
 *
 * @param {number} n - Positive integer representing the number of levels.
 * @returns {number[]} Array of stone counts for each level.
 */
const makeAPile = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('Input must be a positive integer');
  }

  const pile = [];
  let current = n;

  for (let i = 0; i < n; i++) {
    pile.push(current);
    current += 2; // next odd or even number
  }

  return pile;
};
```

