/**
 * Returns an array representing a pile of stones.
 * The first level contains `n` stones. Each subsequent level
 * contains the next odd or even number, depending on the parity
 * of the current level. This is equivalent to adding 2 each time.
 *
 * @param {number} n - The number of levels (positive integer).
 * @returns {number[]} An array of length `n` with the stone counts.
 */
const makeAPile = (n) => {
  // Ensure n is a positive integer; if not, return an empty array.
  if (!Number.isInteger(n) || n <= 0) return [];

  // Generate the sequence by adding 2 for each level.
  return Array.from({ length: n }, (_, i) => n + 2 * i);
};
```

