/**
 * Returns the largest even integer in the inclusive range [x, y].
 * If no even integer exists in the range, returns -1.
 *
 * @param {number} x - Lower bound of the range (positive integer).
 * @param {number} y - Upper bound of the range (positive integer).
 * @returns {number} The largest even integer within [x, y] or -1 if none.
 */
const chooseNum = (x, y) => {
  // Ensure x is the lower bound and y is the upper bound
  if (x > y) return -1;

  // Find the largest even number <= y
  const candidate = (y % 2 === 0) ? y : y - 1;

  // If the candidate is within the range, return it; otherwise, no even number exists
  return candidate >= x ? candidate : -1;
};
