 * Computes the average of all integers from n to m (inclusive),
 * rounds it to the nearest integer, and returns the binary
 * representation prefixed with '0b'. If n > m, returns -1.
 *
 * @param {number} n - The starting integer (positive).
 * @param {number} m - The ending integer (positive).
 * @returns {string|number} Binary string of the rounded average or -1.
 */
const roundedAvg = (n, m) => {
  if (n > m) return -1;

  // The average of an arithmetic sequence is the mean of its endpoints.
  const avg = (n + m) / 2;

  // Round to the nearest integer.
  const rounded = Math.round(avg);

  // Convert to binary string with '0b' prefix.
  return '0b' + rounded.toString(2);
};
```

