/**
 * Computes the rounded average of all integers from n to m (inclusive),
 * returns the result as a binary string prefixed with "0b".
 * If n > m, returns -1.
 *
 * @param {number} n - The starting integer (positive).
 * @param {number} m - The ending integer (positive).
 * @returns {string|number} Binary string of the rounded average or -1.
 */
const roundedAvg = (n, m) => {
  if (n > m) return -1;

  const count = m - n + 1;
  const sum = (n + m) * count / 2;
  const avgRounded = Math.round(sum / count);

  return `0b${avgRounded.toString(2)}`;
};
