/**
 * Returns a sorted array of numbers that contain only odd digits.
 *
 * @param {number[]} x - An array of positive integers.
 * @returns {number[]} A new array containing the numbers from `x` that have no even digit,
 *                     sorted in ascending order.
 */
const uniqueDigits = (x) => {
  return x
    .filter((num) => {
      // Convert the number to a string and check each digit
      return [...String(num)].every((digit) => parseInt(digit, 10) % 2 === 1);
    })
    .sort((a, b) => a - b);
};
