const byLength = (arr) => {
  const names = [
    'One', 'Two', 'Three', 'Four', 'Five',
    'Six', 'Seven', 'Eight', 'Nine'
  ];

  // Keep only integers 1‑9 inclusive
  const filtered = arr.filter(
    (n) => Number.isInteger(n) && n >= 1 && n <= 9
  );

  // Sort ascending, then reverse to get descending
  const sortedDesc = filtered.sort((a, b) => a - b).reverse();

  // Map each digit to its name
  return sortedDesc.map((n) => names[n - 1]);
};
