/**
 * Returns an array of length `n` where the element at position `i`
 * (1‑based) is:
 *   - the factorial of `i` if `i` is even,
 *   - the sum of all integers from 1 to `i` if `i` is odd.
 *
 * @param {number} n - The size of the resulting array (must be ≥ 0).
 * @returns {number[]} The computed array.
 */
const f = (n) => {
  const result = [];
  let factorial = 1; // holds i! for the current i
  let sum = 0;       // holds 1 + 2 + … + i

  for (let i = 1; i <= n; i++) {
    sum += i;
    factorial *= i;

    if (i % 2 === 0) {
      result.push(factorial); // even index → factorial
    } else {
      result.push(sum);       // odd index → sum
    }
  }

  return result;
};
```

