/**
 * Returns a sorted array of numbers from `x` that contain no even digits.
 *
 * @param {number[]} x - Array of positive integers.
 * @returns {number[]} Sorted array of numbers with only odd digits.
 */
const uniqueDigits = (x) => {
  // Helper to check if a number has any even digit
  const hasEvenDigit = (n) => {
    while (n > 0) {
      const digit = n % 10;
      if (digit % 2 === 0) return true; // even digit found
      n = Math.floor(n / 10);
    }
    return false; // no even digits
  };

  // Filter numbers that do not have even digits
  const filtered = x.filter((num) => !hasEvenDigit(num));

  // Sort the result in ascending order
  filtered.sort((a, b) => a - b);

  return filtered;
};
