const countNums = (arr) => {
  let count = 0;

  for (const n of arr) {
    if (n > 0) {
      // Positive numbers (except 0) always have a positive digit sum
      count++;
      continue;
    }

    if (n === 0) continue; // sum of digits is 0

    // Handle negative numbers
    const abs = -n;
    let sum = 0;
    let msd = abs;

    // Find most significant digit and sum all digits
    while (msd >= 10) {
      sum += msd % 10;
      msd = Math.floor(msd / 10);
    }
    sum += msd; // add the most significant digit

    // Apply the negative sign to the most significant digit
    const signedSum = sum - 2 * msd;

    if (signedSum > 0) count++;
  }

  return count;
};
