/**
 * Determines whether an array can be sorted in non‑decreasing order
 * by performing any number of right cyclic shifts.
 *
 * @param {number[]} arr - Array of unique integers.
 * @returns {boolean} true if a sorted array can be obtained, otherwise false.
 */
const moveOneBall = (arr) => {
  const n = arr.length;
  if (n === 0) return true;

  let dropCount = 0;
  let dropIndex = -1;

  for (let i = 0; i < n - 1; i++) {
    if (arr[i] > arr[i + 1]) {
      dropCount++;
      dropIndex = i;
      if (dropCount > 1) return false; // more than one drop → impossible
    }
  }

  // Check the wrap‑around pair (last element to first)
  if (arr[n - 1] > arr[0]) {
    dropCount++;
    if (dropCount > 1) return false;
  }

  // If there are no drops, the array is already sorted
  if (dropCount === 0) return true;

  // Exactly one drop: ensure the last element is <= first element
  return arr[n - 1] <= arr[0];
};
```

