 * Determines whether the array can be sorted in non‑decreasing order
 * by performing any number of right shift operations (cyclic rotations).
 *
 * @param {number[]} arr - The input array of unique integers.
 * @returns {boolean} - True if a rotation can sort the array, otherwise false.
 */
const moveOneBall = (arr) => {
  const n = arr.length;
  if (n <= 1) return true; // empty or single element is already sorted

  // Find the index of the minimum element (rotation point)
  let minIdx = 0;
  for (let i = 1; i < n; i++) {
    if (arr[i] < arr[minIdx]) minIdx = i;
  }

  // Rotate the array so that the minimum element is first
  const rotated = arr.slice(minIdx).concat(arr.slice(0, minIdx));

  // Check if the rotated array is sorted in non‑decreasing order
  for (let i = 1; i < n; i++) {
    if (rotated[i - 1] > rotated[i]) return false;
  }

  return true;
};
