 *
 * @param {number[]} lst1 - The first list of numbers.
 * @param {number[]} lst2 - The second list of numbers.
 * @returns {string} "YES" if it's possible to make all elements of lst1 even, otherwise "NO".
 */
const exchange = (lst1, lst2) => {
  // Count how many odd numbers are in lst1
  const oddInLst1 = lst1.reduce((cnt, val) => cnt + (val % 2 !== 0), 0);

  // Count how many even numbers are available in lst2
  const evenInLst2 = lst2.reduce((cnt, val) => cnt + (val % 2 === 0), 0);

  // We can replace each odd in lst1 with an even from lst2
  return evenInLst2 >= oddInLst1 ? 'YES' : 'NO';
};
