const histogram = (test) => {
  // Return an empty object for an empty input
  if (!test) return {};

  // Split the string on whitespace, ignoring any empty parts
  const letters = test.trim().split(/\s+/).filter(Boolean);
  if (letters.length === 0) return {};

  // Count occurrences of each letter
  const counts = {};
  for (const letter of letters) {
    counts[letter] = (counts[letter] || 0) + 1;
  }

  // Find the maximum count
  const maxCount = Math.max(...Object.values(counts));

  // Build the result object containing all letters with the maximum count
  const result = {};
  for (const [letter, count] of Object.entries(counts)) {
    if (count === maxCount) result[letter] = count;
  }

  return result;
};
