/**
 * Determines whether an array can be sorted in non‑decreasing order
 * by performing any number of right shift operations.
 *
 * @param {number[]} arr - Array of unique integers.
 * @returns {boolean} True if a rotation of the array is sorted, otherwise false.
 */
const moveOneBall = (arr) => {
  const n = arr.length;
  if (n === 0) return true;

  let breakCount = 0;
  for (let i = 0; i < n; i++) {
    const next = (i + 1) % n;
    if (arr[i] > arr[next]) breakCount++;
  }

  if (breakCount === 0) return true;          // already sorted
  if (breakCount === 1 && arr[n - 1] <= arr[0]) return true; // single wrap‑around
  return false;
};
```

