/**
 * Removes all characters from `s` that appear in `c` and checks if the
 * resulting string is a palindrome.
 *
 * @param {string} s - The original string.
 * @param {string} c - The string containing characters to delete.
 * @returns {[string, boolean]} A tuple where the first element is the
 *          resulting string and the second element is `true` if that
 *          string is a palindrome, otherwise `false`.
 */
const reverseDelete = (s, c) => {
  // Build a set of characters to delete for O(1) look‑ups.
  const deleteSet = new Set(c);

  // Filter out characters that are in the delete set.
  const result = [...s].filter(ch => !deleteSet.has(ch)).join('');

  // A string is a palindrome if it equals its reverse.
  const isPalindrome = result === [...result].reverse().join('');

  return [result, isPalindrome];
};
```

