const reverseDelete = (s, c) => {
  // Use a Set for O(1) look‑ups of characters to delete
  const deleteSet = new Set(c);

  // Build the filtered string
  const filtered = [...s].filter(ch => !deleteSet.has(ch)).join('');

  // Check palindrome
  const len = filtered.length;
  let isPal = true;
  for (let i = 0; i < Math.floor(len / 2); i++) {
    if (filtered[i] !== filtered[len - 1 - i]) {
      isPal = false;
      break;
    }
  }

  return [filtered, isPal];
};
