/**
 * Returns the minimum sum of any non‑empty sub‑array of `nums`.
 *
 * Uses a linear‑time variant of Kadane's algorithm.
 *
 * @param {number[]} nums - Array of integers (non‑empty).
 * @returns {number} The smallest possible sub‑array sum.
 */
const minSubArraySum = (nums) => {
  if (!Array.isArray(nums) || nums.length === 0) {
    throw new Error('minSubArraySum requires a non‑empty array of numbers');
  }

  let currentMin = nums[0];
  let globalMin = nums[0];

  for (let i = 1; i < nums.length; i++) {
    const val = nums[i];
    // Either start a new sub‑array at this element or extend the previous one
    currentMin = Math.min(val, currentMin + val);
    // Update the global minimum if needed
    globalMin = Math.min(globalMin, currentMin);
  }

  return globalMin;
};
```

