/**
 * Returns the minimum sum of any non‑empty sub‑array of `nums`.
 *
 * Uses a linear‑time variant of Kadane's algorithm that tracks the
 * minimum sub‑array sum ending at each position.
 *
 * @param {number[]} nums - Array of integers (must contain at least one element)
 * @returns {number} The smallest possible sum of a contiguous sub‑array
 */
const minSubArraySum = (nums) => {
  if (!Array.isArray(nums) || nums.length === 0) {
    throw new Error('minSubArraySum requires a non‑empty array of numbers');
  }

  let currentMin = nums[0];   // Minimum sum ending at current index
  let globalMin = nums[0];    // Minimum sum found so far

  for (let i = 1; i < nums.length; i++) {
    // Either start a new sub‑array at nums[i] or extend the previous one
    currentMin = Math.min(nums[i], currentMin + nums[i]);

    // Update the global minimum if needed
    if (currentMin < globalMin) {
      globalMin = currentMin;
    }
  }

  return globalMin;
};
