  let globalMin = nums[0];    // Minimum sum found so far

  for (let i = 1; i < nums.length; i++) {
    // Either start a new sub‑array at nums[i] or extend the previous one
    currentMin = Math.min(nums[i], currentMin + nums[i]);

    // Update the global minimum if needed
    if (currentMin < globalMin) {
      globalMin = currentMin;
    }
  }

  return globalMin;
};

