 */
const maxFill = (grid, capacity) => {
  if (!Array.isArray(grid) || grid.length === 0) return 0;
  let total = 0;

  for (const row of grid) {
    // Count the number of water units in this well
    const waterUnits = row.reduce((sum, val) => sum + (val === 1 ? 1 : 0), 0);

    // If there is water, add the number of bucket lowers needed for this well
    if (waterUnits > 0) {
      total += Math.ceil(waterUnits / capacity);
    }
  }

  return total;
};
