/**
 * Count the number of '1' bits in the binary representation of a number.
 * Works for both positive and negative integers by ignoring the sign.
 *
 * @param {number} n
 * @returns {number}
 */
const countOnes = (n) => {
  // Convert to binary string, strip a leading '-' if present,
  // then count the '1' characters.
  const bin = Math.abs(n).toString(2);
  let count = 0;
  for (let i = 0; i < bin.length; i++) {
    if (bin[i] === '1') count++;
  }
  return count;
};

/**
 * Sort an array of integers by the number of ones in their binary
 * representation (ascending). If two numbers have the same count,
 * they are sorted by their decimal value (ascending).
 *
 * @param {number[]} arr
 * @returns {number[]}
 */
const sortArray = (arr) => {
  // Work on a copy to avoid mutating the original array
  const result = arr.slice();

  result.sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);

    if (onesA !== onesB) {
      return onesA - onesB; // ascending by number of ones
    }
    return a - b; // ascending by decimal value
  });

  return result;
};
