/**
 * Returns all words from the string `s` that contain exactly `n` consonants.
 * Words are separated by whitespace. The function preserves the original
 * word order and is case‑insensitive when counting consonants.
 *
 * @param {string} s - The input string containing only letters and spaces.
 * @param {number} n - The exact number of consonants a word must contain.
 * @returns {string[]} An array of words that meet the consonant count criterion.
 */
const selectWords = (s, n) => {
  // If the string is empty or only whitespace, return an empty array.
  if (!s || s.trim() === '') return [];

  const vowels = new Set('aeiouAEIOU');
  const words = s.trim().split(/\s+/); // split on one or more whitespace characters
  const result = [];

  for (const word of words) {
    let consonantCount = 0;
    for (const ch of word) {
      // Count only alphabetic characters that are not vowels.
      if (!vowels.has(ch)) consonantCount++;
    }
    if (consonantCount === n) result.push(word);
  }

  return result;
};
