/**
 * Sort an array of integers by the number of 1‑bits in their binary representation.
 * For equal bit counts, sort by the numeric value.
 * Negative numbers are sorted by numeric value only and placed after non‑negative numbers.
 *
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new array sorted according to the rules.
 */
const sortArray = (arr) => {
  // Helper to count 1‑bits in the binary representation of a non‑negative integer.
  const countOnes = (n) => {
    let count = 0;
    let x = Math.abs(n); // use absolute value for counting bits
    while (x > 0) {
      count += x % 2;
      x = Math.floor(x / 2);
    }
    return count;
  };

  // Create a shallow copy so the original array is not mutated.
  return arr.slice().sort((a, b) => {
    const aNeg = a < 0;
    const bNeg = b < 0;

    // If both are negative, sort by numeric value.
    if (aNeg && bNeg) return a - b;

    // If only one is negative, the negative one comes after the non‑negative one.
    if (aNeg) return 1;
    if (bNeg) return -1;

    // Both are non‑negative: compare by bit count first, then by numeric value.
    const ca = countOnes(a);
    const cb = countOnes(b);
    if (ca !== cb) return ca - cb;
    return a - b;
  });
};
