/**
 * Checks whether a string consisting only of '(' and ')' is balanced.
 * @param {string} s - The string to check.
 * @returns {boolean} - True if balanced, false otherwise.
 */
const isBalanced = (s) => {
  let balance = 0;
  for (const ch of s) {
    if (ch === '(') {
      balance++;
    } else { // ch === ')'
      balance--;
    }
    if (balance < 0) return false; // more closing than opening at some point
  }
  return balance === 0;
};

/**
 * Determines if the two strings can be concatenated in some order to form a balanced string.
 * @param {[string, string]} lst - Array containing exactly two strings of '(' and ')'.
 * @returns {string} - 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  const [a, b] = lst;
  return isBalanced(a + b) || isBalanced(b + a) ? 'Yes' : 'No';
};
