/**
 * Returns the closest vowel (from the right) that is surrounded by consonants.
 * Vowels at the start or end of the word are ignored.
 *
 * @param {string} word - The input word containing only English letters.
 * @returns {string} The vowel found, or an empty string if none matches.
 */
const getClosestVowel = (word) => {
  const vowels = new Set('AEIOUaeiou');

  // No possible vowel between two consonants if word length < 3
  if (word.length < 3) return '';

  for (let i = word.length - 1; i >= 0; i--) {
    const ch = word[i];
    if (!vowels.has(ch)) continue;          // skip consonants

    // Skip vowels at the boundaries
    if (i === 0 || i === word.length - 1) continue;

    const left = word[i - 1];
    const right = word[i + 1];

    // Check if both neighbors are consonants
    if (!vowels.has(left) && !vowels.has(right)) {
      return ch;
    }
  }

  return '';
};
