  if (word.length < 3) return '';

  // Search from right to left
  for (let i = word.length - 2; i > 0; i--) {
    if (
      isVowel(word[i]) &&          // current char is a vowel
      !isVowel(word[i - 1]) &&     // left neighbour is a consonant
      !isVowel(word[i + 1])        // right neighbour is a consonant
    ) {
      return word[i];
    }
  }

