/**
 * Determine if two strings of parentheses can be concatenated in some order
 * to form a balanced string.
 *
 * @param {string[]} lst - Array of two strings containing only '(' and ')'.
 * @returns {string} 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  // Helper to compute net balance and minimum prefix balance of a string
  const analyze = (s) => {
    let bal = 0;
    let minPref = 0;
    for (const ch of s) {
      bal += ch === '(' ? 1 : -1;
      if (bal < minPref) minPref = bal;
    }
    return { net: bal, minPref };
  };

  const [s1, s2] = lst;
  const a1 = analyze(s1);
  const a2 = analyze(s2);

  // Check order s1 + s2
  if (
    a1.net + a2.net === 0 &&
    a1.minPref >= 0 &&
    a1.net + a2.minPref >= 0
  ) {
    return 'Yes';
  }

  // Check order s2 + s1
  if (
    a2.net + a1.net === 0 &&
    a2.minPref >= 0 &&
    a2.net + a1.minPref >= 0
  ) {
    return 'Yes';
  }

  return 'No';
};
