/**
 * Returns the k largest numbers from `arr`, sorted in ascending order.
 *
 * @param {number[]} arr - The input array of integers.
 * @param {number} k   - The number of maximum elements to return.
 * @returns {number[]} A new array containing the k largest elements, sorted ascending.
 */
const maximum = (arr, k) => {
  if (k === 0) return [];

  // Work on a copy to avoid mutating the original array
  const sorted = [...arr].sort((a, b) => a - b);

  // Take the last k elements (the largest ones) and return them
  return sorted.slice(-k);
};
