/**
 * Returns the sum of elements with at most two digits
 * from the first `k` elements of the array `arr`.
 *
 * @param {number[]} arr - Non‑empty array of integers.
 * @param {number} k   - Number of elements to consider from the start of `arr`.
 * @returns {number}   - Sum of qualifying elements.
 */
const addElements = (arr, k) => {
  let sum = 0;
  // Ensure we don't go out of bounds if k > arr.length
  const limit = Math.min(k, arr.length);

  for (let i = 0; i < limit; i++) {
    // At most two digits means absolute value < 100
    if (Math.abs(arr[i]) < 100) {
      sum += arr[i];
    }
  }

  return sum;
};
