/**
 * Returns a sorted array of the odd numbers that appear in the Collatz sequence
 * starting from the given positive integer `n`.
 *
 * @param {number} n - A positive integer.
 * @returns {number[]} Sorted list of odd numbers in the Collatz sequence.
 */
const getOddCollatz = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('n must be a positive integer');
  }

  const odds = [];
  let t = n;

  while (true) {
    if (t % 2 === 1) {
      odds.push(t);
    }

    if (t === 1) break;

    t = (t % 2 === 0) ? t / 2 : 3 * t + 1;
  }

  odds.sort((a, b) => a - b);
  return odds;
};
