/**
 * Validates a date string in the format mm-dd-yyyy.
 *
 * Rules:
 * 1. The string must not be empty.
 * 2. The format must be exactly two digits for month, two digits for day,
 *    four digits for year, separated by hyphens.
 * 3. Month must be between 1 and 12.
 * 4. Day must be within the valid range for the given month
 *    (31 for Jan, Mar, May, Jul, Aug, Oct, Dec;
 *     30 for Apr, Jun, Sep, Nov;
 *     29 for Feb).
 *
 * @param {string} date - The date string to validate.
 * @returns {boolean} - True if the date is valid, false otherwise.
 */
const validDate = (date) => {
  if (!date) return false; // Rule 1

  const parts = date.split('-');
  if (parts.length !== 3) return false; // Must have 3 parts

  const [mm, dd, yyyy] = parts;

  // Rule 4: exact lengths
  if (mm.length !== 2 || dd.length !== 2 || yyyy.length !== 4) return false;

  // All parts must be numeric
  if (!/^\d+$/.test(mm) || !/^\d+$/.test(dd) || !/^\d+$/.test(yyyy)) return false;

  const month = parseInt(mm, 10);
  const day = parseInt(dd, 10);
  // Year is not used for validation beyond numeric check

  // Rule 3: month range
  if (month < 1 || month > 12) return false;

  // Determine max days for the month
  let maxDay;
  if ([1, 3, 5, 7, 8, 10, 12].includes(month)) {
    maxDay = 31;
  } else if ([4, 6, 9, 11].includes(month)) {
    maxDay = 30;
  } else if (month === 2) {
    maxDay = 29; // February
  } else {
    return false; // Should never happen
  }

  // Rule 2: day range
  if (day < 1 || day > maxDay) return false;

  return true;
};
