/**
 * Validates a date string in the format mm-dd-yyyy.
 *
 * Rules:
 * 1. The string must not be empty.
 * 2. The format must be exactly two digits for month, two digits for day,
 *    and four digits for year, separated by hyphens.
 * 3. Month must be between 1 and 12.
 * 4. Day must be between 1 and the maximum number of days for that month
 *    (31 for months 1,3,5,7,8,10,12; 30 for months 4,6,9,11; 29 for month 2).
 *
 * @param {string} date - The date string to validate.
 * @returns {boolean} True if the date is valid, otherwise false.
 */
const validDate = (date) => {
  if (!date) return false;

  // Ensure the format mm-dd-yyyy with leading zeros
  const formatRegex = /^\d{2}-\d{2}-\d{4}$/;
  if (!formatRegex.test(date)) return false;

  const [mmStr, ddStr, yyyyStr] = date.split('-');
  const month = Number(mmStr);
  const day   = Number(ddStr);
  const year  = Number(yyyyStr); // year is not used for validation but parsed for completeness

  // Basic numeric checks
  if (isNaN(month) || isNaN(day) || isNaN(year)) return false;

  // Month bounds
  if (month < 1 || month > 12) return false;

  // Day bounds
  if (day < 1) return false;

  // Days per month (February always allows up to 29)
  const daysInMonth = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day > daysInMonth[month - 1]) return false;

  return true;
};
