 *    - 02                    → 1–29 (leap‑year logic is not required)
 *
 * @param {string} date - The date string to validate.
 * @returns {boolean} True if the date is valid, otherwise false.
 */
const validDate = (date) => {
  // 1. Non‑empty string check
  if (typeof date !== 'string' || date.trim() === '') return false;

  // 2. Format check: mm-dd-yyyy with leading zeros
  const formatRegex = /^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-(\d{4})$/;
  if (!formatRegex.test(date)) return false;

  // 3. Extract numeric parts
  const [mmStr, ddStr] = date.split('-');
  const month = Number(mmStr);
  const day   = Number(ddStr);

  // 4. Day range validation per month
  if (month === 2) {
    if (day > 29) return false;
  } else if ([1, 3, 5, 7, 8, 10, 12].includes(month)) {
    if (day > 31) return false;
  } else { // months 4, 6, 9, 11
    if (day > 30) return false;
  }

  return true;
};

