/**
 * Splits a string into words or counts odd‑ordered lowercase letters.
 *
 * @param {string} txt - The input string.
 * @returns {string[]|number} An array of words if whitespace or commas are present,
 *                            otherwise the count of lowercase letters with odd
 *                            alphabetical order (a=0, b=1, …, z=25).
 */
const splitWords = (txt) => {
  // 1. Split on whitespace if any exists
  if (/\s/.test(txt)) {
    return txt.trim().split(/\s+/).filter(Boolean);
  }

  // 2. Split on commas if any exists
  if (/,/.test(txt)) {
    return txt.split(',').filter(Boolean);
  }

  // 3. Count lowercase letters with odd order in the alphabet
  let count = 0;
  for (let i = 0; i < txt.length; i++) {
    const code = txt.charCodeAt(i);
    if (code >= 97 && code <= 122) {          // 'a' to 'z'
      const order = code - 97;                // 0 for 'a', 1 for 'b', …
      if (order % 2 === 1) {                  // odd order
        count++;
      }
    }
  }
  return count;
};
