/**
 * Checks whether a list of non‑negative integers is sorted in ascending order
 * and contains at most two consecutive duplicates of any number.
 *
 * @param {number[]} lst - The list to check.
 * @returns {boolean} True if the list satisfies the conditions, otherwise false.
 */
const isSorted = (lst) => {
  if (lst.length <= 1) return true; // empty or single element is trivially sorted

  let prev = lst[0];
  let dupCount = 1; // count of consecutive occurrences of prev

  for (let i = 1; i < lst.length; i++) {
    const curr = lst[i];

    if (curr < prev) return false;          // not ascending

    if (curr === prev) {
      dupCount++;
      if (dupCount > 2) return false;       // more than two duplicates
    } else {
      prev = curr;
      dupCount = 1;                         // reset duplicate counter
    }
  }

  return true;
};
```

