/**
 * Returns "YES" if the length of the intersection of two closed integer intervals
 * is a prime number, otherwise returns "NO".
 *
 * @param {[number, number]} interval1 - [start1, end1]
 * @param {[number, number]} interval2 - [start2, end2]
 * @returns {string} "YES" or "NO"
 */
const intersection = (interval1, interval2) => {
  const [s1, e1] = interval1;
  const [s2, e2] = interval2;

  // Compute intersection bounds
  const start = Math.max(s1, s2);
  const end   = Math.min(e1, e2);

  // No intersection
  if (start > end) return 'NO';

  // Length of closed interval
  const length = end - start + 1;

  return isPrime(length) ? 'YES' : 'NO';
};

/**
 * Checks whether a positive integer n is prime.
 *
 * @param {number} n
 * @returns {boolean}
 */
const isPrime = (n) => {
  if (n < 2) return false;
  if (n === 2) return true;
  if (n % 2 === 0) return false;
  const limit = Math.floor(Math.sqrt(n));
  for (let i = 3; i <= limit; i += 2) {
    if (n % i === 0) return false;
  }
  return true;
};
