/**
 * Returns the sum of magnitudes of the integers in `arr` multiplied by the product
 * of their signs (1, -1, or 0). Returns `null` if the array is empty.
 *
 * @param {number[]} arr - Array of integers.
 * @returns {number|null} The computed value or `null` for an empty array.
 */
const prodSigns = (arr) => {
  if (!Array.isArray(arr) || arr.length === 0) return null;

  let sum = 0;          // Sum of absolute values
  let signProduct = 1;  // Product of signs

  for (const num of arr) {
    if (num === 0) return 0;          // Any zero makes the product zero
    sum += Math.abs(num);
    if (num < 0) signProduct *= -1;   // Flip sign for negative numbers
  }

  return sum * signProduct;
};
```

