/**
 * Checks whether a string consisting only of '(' and ')' is balanced.
 * @param {string} s - The string to check.
 * @returns {boolean} - True if the string is balanced, false otherwise.
 */
const isBalanced = (s) => {
  let balance = 0;
  for (const ch of s) {
    if (ch === '(') {
      balance++;
    } else if (ch === ')') {
      balance--;
    }
    // If at any point we have more ')' than '(', it's not balanced.
    if (balance < 0) return false;
  }
  // At the end, all parentheses must be closed.
  return balance === 0;
};

/**
 * Determines if the two given strings can be concatenated in some order
 * to form a balanced parentheses string.
 * @param {string[]} lst - An array of two strings, each containing only '(' or ')'.
 * @returns {string} - 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  const [a, b] = lst;
  if (isBalanced(a + b) || isBalanced(b + a)) {
    return 'Yes';
  }
  return 'No';
};
