 * to form a balanced parentheses string.
 * @param {string[]} lst - An array of two strings, each containing only '(' or ')'.
 * @returns {string} - 'Yes' if a balanced concatenation exists, otherwise 'No'.
 */
const matchParens = (lst) => {
  const [a, b] = lst;
  if (isBalanced(a + b) || isBalanced(b + a)) {
    return 'Yes';
  }
  return 'No';
};

