/**
 * Returns the lexicographically minimal path of length `k` in the given grid.
 *
 * The grid contains all integers from 1 to N*N exactly once.
 * A path may revisit cells and must move only to orthogonally adjacent cells.
 *
 * @param {number[][]} grid - N x N grid of unique integers.
 * @param {number} k - Length of the path (number of cells visited).
 * @returns {number[]} The values along the minimal path.
 */
const minPath = (grid, k) => {
  const N = grid.length;
  let r1 = -1, c1 = -1;

  // Find the coordinates of the cell containing value 1
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (grid[i][j] === 1) {
        r1 = i;
        c1 = j;
        break;
      }
    }
    if (r1 !== -1) break;
  }

  // Find the smallest neighbor value of the cell containing 1
  const dirs = [
    [-1, 0], // up
    [1, 0],  // down
    [0, -1], // left
    [0, 1]   // right
  ];

  let minNeighbor = Infinity;
  for (const [dr, dc] of dirs) {
    const nr = r1 + dr;
    const nc = c1 + dc;
    if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
      minNeighbor = Math.min(minNeighbor, grid[nr][nc]);
    }
  }

  // Build the minimal path: 1, minNeighbor, 1, minNeighbor, ...
  const result = new Array(k);
  for (let i = 0; i < k; i++) {
    result[i] = (i % 2 === 0) ? 1 : minNeighbor;
  }

  return result;
};
