/**
 * Finds the lexicographically smallest path of length `k` in a grid.
 *
 * @param {number[][]} grid - N x N grid with unique values 1..N*N.
 * @param {number} k - Length of the path (number of cells visited).
 * @returns {number[]} The values along the minimal path.
 */
const minPath = (grid, k) => {
  const N = grid.length;
  if (k <= 0) return [];

  // Locate the cell containing value 1 (the smallest possible start).
  let startRow = -1, startCol = -1;
  for (let r = 0; r < N; r++) {
    for (let c = 0; c < N; c++) {
      if (grid[r][c] === 1) {
        startRow = r;
        startCol = c;
        break;
      }
    }
    if (startRow !== -1) break;
  }

  const result = [1];
  if (k === 1) return result;

  let r = startRow, c = startCol;

  // Directions: up, down, left, right
  const dirs = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  for (let step = 1; step < k; step++) {
    let bestVal = Infinity;
    let bestR = r, bestC = c;

    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
        const val = grid[nr][nc];
        if (val < bestVal) {
          bestVal = val;
          bestR = nr;
          bestC = nc;
        }
      }
    }

    // Move to the chosen neighbor
    r = bestR;
    c = bestC;
    result.push(bestVal);
  }

  return result;
};
