/**
 * Returns the first n + 1 terms of the Tribonacci sequence.
 *
 * The sequence is defined as:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * For odd n, tri(n+1) is always even, so it can be computed directly.
 *
 * @param {number} n - non‑negative integer
 * @returns {number[]} array of length n + 1 containing the sequence
 */
const tri = (n) => {
  if (n < 0) throw new Error('n must be a non‑negative integer');

  // Base cases
  if (n === 0) return [1];
  if (n === 1) return [1, 3];

  const seq = [1, 3];

  for (let i = 2; i <= n; i++) {
    if (i % 2 === 0) {
      // Even index
      seq.push(1 + i / 2);
    } else {
      // Odd index: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
      // tri(i+1) is even, so 1 + (i+1)/2
      const nextEven = 1 + (i + 1) / 2;
      seq.push(seq[i - 1] + seq[i - 2] + nextEven);
    }
  }

  return seq;
};
