/**
 * Returns the first n + 1 terms of the Tribonacci sequence.
 *
 * The sequence is defined as:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * @param {number} n - non‑negative integer
 * @returns {number[]} array of length n + 1 containing the sequence
 */
const tri = (n) => {
  if (n < 0) throw new Error('n must be a non‑negative integer');

  const seq = new Array(n + 1);
  seq[0] = 1;
  if (n >= 1) seq[1] = 3;

  for (let i = 2; i <= n; i++) {
    if (i % 2 === 0) {
      // Even index – direct formula
      seq[i] = 1 + i / 2;
    } else {
      // Odd index – depends on the next even term
      const next = i + 1;
      const nextVal = next <= n ? (seq[next] ?? (1 + next / 2)) : (1 + next / 2);

      // Store the next even term if it hasn't been computed yet
      if (next <= n && seq[next] === undefined) seq[next] = nextVal;

      seq[i] = seq[i - 1] + seq[i - 2] + nextVal;
    }
  }

  return seq;
};
