/**
 * Returns the sum of the squares of the ceiling of each number in the list.
 *
 * @param {number[]} lst - An array of numbers.
 * @returns {number} The sum of squared ceiling values.
 */
const sumSquares = (lst) => {
  return lst.reduce((sum, num) => {
    const ceilVal = Math.ceil(num);
    return sum + ceilVal * ceilVal;
  }, 0);
};
