/**
 * Returns the first n + 1 numbers of the Tribonacci sequence.
 *
 * The sequence is defined as:
 *   tri(0) = 1
 *   tri(1) = 3
 *   tri(n) = 1 + n / 2          if n is even
 *   tri(n) = tri(n‑1) + tri(n‑2) + tri(n+1)  if n is odd
 *
 * @param {number} n - non‑negative integer
 * @returns {number[]} array of length n + 1
 */
const tri = (n) => {
  // Allocate array for indices 0 … n+1 (n+1 may be needed for odd n)
  const seq = new Array(n + 2);

  // Base values
  seq[0] = 1;          // even
  if (n >= 1) seq[1] = 3;

  // Compute all even indices up to n+1
  for (let i = 2; i <= n + 1; i++) {
    if (i % 2 === 0) {
      seq[i] = 1 + i / 2;
    }
  }

  // Compute odd indices in increasing order
  // (each odd index depends on the previous odd index)
  for (let i = 3; i <= n; i += 2) {
    // i-1 is even, i-2 is odd (already computed), i+1 is even
    seq[i] = seq[i - 1] + seq[i - 2] + seq[i + 1];
  }

  // Return the first n+1 numbers (indices 0 … n)
  return seq.slice(0, n + 1);
};
