/**
 * Returns true if the input string of '[' and ']' contains a valid
 * subsequence of brackets that has at least one nested pair.
 *
 * A nested pair exists when we can pick indices i < j < k < l such that
 *   s[i] === '['
 *   s[j] === '['
 *   s[k] === ']'
 *   s[l] === ']'
 * and j < k (the second opening bracket is inside the first pair).
 *
 * @param {string} s - String containing only '[' and ']'.
 * @returns {boolean}
 */
const isNested = (s) => {
  // Find the first '['
  let firstOpen = -1;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') {
      firstOpen = i;
      break;
    }
  }
  if (firstOpen === -1) return false;

  // Find the second '[' after the first
  let secondOpen = -1;
  for (let i = firstOpen + 1; i < s.length; i++) {
    if (s[i] === '[') {
      secondOpen = i;
      break;
    }
  }
  if (secondOpen === -1) return false;

  // Find the first ']' after the second '['
  let firstClose = -1;
  for (let i = secondOpen + 1; i < s.length; i++) {
    if (s[i] === ']') {
      firstClose = i;
      break;
    }
  }
  if (firstClose === -1) return false;

  // Find the second ']' after the first close
  let secondClose = -1;
  for (let i = firstClose + 1; i < s.length; i++) {
    if (s[i] === ']') {
      secondClose = i;
      break;
    }
  }
  return secondClose !== -1;
};
```

