/**
 * Returns true if the input string of brackets contains a valid subsequence
 * that has at least one nested pair of brackets.
 *
 * A nested subsequence exists iff we can find indices
 * a < b < c < d such that:
 *   string[a] === '['
 *   string[b] === '['
 *   string[c] === ']'
 *   string[d] === ']'
 *
 * The function simply looks for the earliest possible such indices.
 */
const isNested = (string) => {
  // Find the first two '['
  let firstOpen = -1;
  let secondOpen = -1;
  for (let i = 0; i < string.length; i++) {
    if (string[i] === '[') {
      if (firstOpen === -1) {
        firstOpen = i;
      } else if (secondOpen === -1) {
        secondOpen = i;
        break; // we only need two opens
      }
    }
  }

  // If we don't have two opens, no nested subsequence is possible
  if (firstOpen === -1 || secondOpen === -1) return false;

  // Find the first two ']' after the second '['
  let firstClose = -1;
  let secondClose = -1;
  for (let i = secondOpen + 1; i < string.length; i++) {
    if (string[i] === ']') {
      if (firstClose === -1) {
        firstClose = i;
      } else {
        secondClose = i;
        break; // we only need two closes
      }
    }
  }

  // A nested subsequence exists only if we found two closes
  return secondClose !== -1;
};
