const isNested = (string) => {
  const n = string.length;
  // suffixClose[i] = number of ']' from index i to end
  const suffixClose = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffixClose[i] = suffixClose[i + 1] + (string[i] === ']' ? 1 : 0);
  }

  let openBefore = 0; // count of '[' seen so far
  for (let i = 0; i < n; i++) {
    if (string[i] === '[') {
      // need at least one '[' before this and at least two ']' after it
      if (openBefore >= 1 && suffixClose[i + 1] >= 2) {
        return true;
      }
      openBefore++;
    }
  }
  return false;
};
