/**
 * Returns an array [largestNegative, smallestPositive] from the given list.
 * If no negative or positive integers are present, the corresponding value is null.
 *
 * @param {number[]} lst - Array of numbers to inspect.
 * @returns {[number|null, number|null]} Tuple of largest negative and smallest positive.
 */
const largestSmallestIntegers = (lst) => {
  let largestNegative = -Infinity; // largest among negatives
  let smallestPositive = Infinity; // smallest among positives

  for (const num of lst) {
    if (num < 0 && num > largestNegative) {
      largestNegative = num;
    } else if (num > 0 && num < smallestPositive) {
      smallestPositive = num;
    }
  }

  if (largestNegative === -Infinity) largestNegative = null;
  if (smallestPositive === Infinity) smallestPositive = null;

  return [largestNegative, smallestPositive];
};
