/**
 * Compare two values that can be numbers or numeric strings.
 * Returns the larger value in its original type, or null if they are equal.
 *
 * @param {number|string} a
 * @param {number|string} b
 * @returns {number|string|null}
 */
const compareOne = (a, b) => {
  // Helper to convert a value to a numeric representation
  const toNumber = (v) => {
    if (typeof v === 'number') return v;
    // Replace comma with dot for decimal separator
    const normalized = String(v).replace(/,/g, '.');
    return parseFloat(normalized);
  };

  const numA = toNumber(a);
  const numB = toNumber(b);

  if (numA === numB) return null;

  return numA > numB ? a : b;
};
```

