/**
 * Determines whether a given number can be expressed as the sum of exactly
 * four positive even integers.
 *
 * @param {number} n - The number to evaluate.
 * @returns {boolean} True if n can be written as the sum of four positive even numbers, otherwise false.
 */
const isEqualToSumEven = (n) => {
  // Each even number must be at least 2, so the minimal sum is 8.
  // The sum of even numbers is always even.
  return Number.isInteger(n) && n >= 8 && n % 2 === 0;
};
