/**
 * Computes the Brazilian (special) factorial of a positive integer n.
 * The result is the product of all factorials from 1! up to n!.
 *
 * @param {number} n - A positive integer (n > 0)
 * @returns {bigint} The special factorial as a BigInt
 * @throws {TypeError} If n is not a positive integer
 */
const specialFactorial = (n) => {
  if (!Number.isInteger(n) || n <= 0) {
    throw new TypeError('Input must be a positive integer');
  }

  let result = 1n;      // Accumulates the product of factorials
  let currentFact = 1n; // Holds the current factorial value

  for (let i = 1; i <= n; i++) {
    currentFact *= BigInt(i); // i! = (i-1)! * i
    result *= currentFact;    // Multiply into the final product
  }

  return result;
};
```

