const fileNameCheck = (file_name) => {
  // Must contain exactly one dot
  const parts = file_name.split('.');
  if (parts.length !== 2) return 'No';

  const [name, ext] = parts;

  // Substring before dot must not be empty and start with a Latin letter
  if (!name || !/^[A-Za-z]/.test(name)) return 'No';

  // Substring after dot must be one of the allowed extensions
  const allowedExts = ['txt', 'exe', 'dll'];
  if (!allowedExts.includes(ext)) return 'No';

  // Count digits in the entire file name (including extension)
  const digitCount = (file_name.match(/\d/g) || []).length;
  if (digitCount > 3) return 'No';

  return 'Yes';
};
```

