const fileNameCheck = (file_name) => {
  // Split the string by '.' and ensure there is exactly one dot
  const parts = file_name.split('.');
  if (parts.length !== 2) return 'No';

  const [name, ext] = parts;

  // The part before the dot must not be empty
  if (!name) return 'No';

  // The first character of the name must be a Latin letter
  if (!/^[A-Za-z]/.test(name)) return 'No';

  // Count digits in the name part (the extension contains no digits)
  const digitCount = (name.match(/\d/g) || []).length;
  if (digitCount > 3) return 'No';

  // The extension must be one of the allowed values
  if (!['txt', 'exe', 'dll'].includes(ext)) return 'No';

  return 'Yes';
