/**
 * Returns a string containing only the words from the input sentence
 * whose lengths are prime numbers, preserving the original order.
 *
 * @param {string} sentence - The input sentence containing only letters and spaces.
 * @returns {string} A space‑separated string of prime‑length words.
 */
const wordsInSentence = (sentence) => {
  // Helper to determine if a number is prime
  const isPrime = (n) => {
    if (n < 2) return false;          // 0 and 1 are not prime
    if (n === 2) return true;         // 2 is the only even prime
    if (n % 2 === 0) return false;    // eliminate even numbers > 2
    const limit = Math.floor(Math.sqrt(n));
    for (let i = 3; i <= limit; i += 2) {
      if (n % i === 0) return false;
    }
    return true;
  };

  // Split the sentence into words (handles multiple spaces)
  const words = sentence.trim().split(/\s+/);

  // Filter words whose lengths are prime
  const primeWords = words.filter((w) => isPrime(w.length));

  // Join back into a string; if none, return an empty string
  return primeWords.join(' ');
};
