/**
 * Compare two values that can be numbers or numeric strings.
 * Returns the larger value in its original type, or null if they are equal.
 *
 * @param {number|string} a - First value (number or numeric string)
 * @param {number|string} b - Second value (number or numeric string)
 * @returns {number|string|null} The larger value in its original type, or null if equal
 */
const compareOne = (a, b) => {
  // Helper to convert a value to a numeric value
  const toNumber = (x) => {
    if (typeof x === 'string') {
      // Normalize decimal separator: comma → dot
      const normalized = x.replace(',', '.');
      const n = Number(normalized);
      return isNaN(n) ? NaN : n;
    }
    return Number(x);
  };

  const numA = toNumber(a);
  const numB = toNumber(b);

  if (numA > numB) return a;
  if (numA < numB) return b;
  return null;
};
