/**
 * Returns true if the product of two fractions is a whole number.
 *
 * @param {string} x - First fraction in the form "numerator/denominator".
 * @param {string} n - Second fraction in the form "numerator/denominator".
 * @returns {boolean} True if the product is an integer, otherwise false.
 */
const simplify = (x, n) => {
  // Parse the fractions into BigInt components
  const [xNum, xDen] = x.split('/').map(BigInt);
  const [nNum, nDen] = n.split('/').map(BigInt);

  // Compute the product numerator and denominator
  const productNum = xNum * nNum;
  const productDen = xDen * nDen;

  // The product is an integer if the denominator divides the numerator evenly
  return productNum % productDen === 0n;
};
