/**
 * Returns the sum of the decimal digits of a number (ignoring the sign).
 * @param {number} n
 * @returns {number}
 */
const digitSum = (n) => {
  let sum = 0;
  let m = Math.abs(n);
  if (m === 0) return 0;
  while (m > 0) {
    sum += m % 10;
    m = Math.floor(m / 10);
  }
  return sum;
};

/**
 * Sorts an array of integers in ascending order according to the sum of their digits.
 * If two numbers have the same digit sum, the one that appeared later in the original
 * array comes first (i.e., original index descending).
 *
 * @param {number[]} nums
 * @returns {number[]}
 */
const orderByPoints = (nums) => {
  return nums
    .map((num, idx) => ({ num, idx, sum: digitSum(num) }))
    .sort((a, b) => {
      if (a.sum !== b.sum) return a.sum - b.sum;
      return b.idx - a.idx; // original index descending for ties
    })
    .map(item => item.num);
};
