/**
 * Computes the “digit sum” used by the original algorithm.
 * For non‑negative numbers it is the ordinary sum of digits.
 * For negative numbers it is the sum of digits of the absolute value
 * minus twice the most significant digit (i.e. the sign is applied only
 * to the most significant digit).
 *
 * @param {number} n
 * @returns {number}
 */
const digitSumWithSign = (n) => {
  const abs = Math.abs(n);
  const str = abs.toString();
  const msd = parseInt(str[0], 10);
  const sumDigits = str.split('').reduce((s, d) => s + parseInt(d, 10), 0);

  return n >= 0 ? sumDigits : sumDigits - 2 * msd;
};

/**
 * Sorts an array of integers in ascending order according to the
 * digit sum defined by `digitSumWithSign`.  When two numbers have
 * the same digit sum, the one that appeared later in the original
 * array comes first (i.e. original index descending).
 *
 * @param {number[]} nums
 * @returns {number[]}
 */
const orderByPoints = (nums) => {
  // Attach original index and computed sum to each element
  const items = nums.map((num, idx) => ({
    num,
    idx,
    sum: digitSumWithSign(num),
  }));

  // Sort by sum ascending; for equal sums, by original index descending
  items.sort((a, b) => {
    if (a.sum !== b.sum) return a.sum - b.sum;
    return b.idx - a.idx;
  });

  // Extract sorted numbers
  return items.map((item) => item.num);
};
