/**
 * Returns the number of triples (a[i], a[j], a[k]) with i < j < k
 * such that a[i] + a[j] + a[k] is a multiple of 3.
 *
 * a[i] = i * i - i + 1  (1‑based index)
 *
 * @param {number} n - Length of the array (positive integer)
 * @returns {number} Number of valid triples
 */
const getMaxTriples = (n) => {
  if (n < 3) return 0;

  // Count indices i (1‑based) where a[i] ≡ 0 (mod 3)
  // a[i] ≡ 0 (mod 3) iff i ≡ 2 (mod 3)
  const count0 = Math.floor((n + 1) / 3); // number of i ≡ 2 (mod 3)
  const count1 = n - count0;              // remaining indices (≡ 0 or 1 mod 3)

  const comb3 = (x) => (x < 3 ? 0 : (x * (x - 1) * (x - 2)) / 6);

  return comb3(count0) + comb3(count1);
};
