 * @returns {number} Number of valid triples
 */
const getMaxTriples = (n) => {
  if (n < 3) return 0;

  // Count residues of a[i] modulo 3
  // a[i] mod 3 depends only on i mod 3:
  // i % 3 === 1 -> residue 0
  // i % 3 === 2 -> residue 2
  // i % 3 === 0 -> residue 1
  const c0 = Math.floor((n + 2) / 3); // i % 3 === 1
  const c1 = Math.floor(n / 3);       // i % 3 === 0
  const c2 = Math.floor((n + 1) / 3); // i % 3 === 2

  const comb3 = (x) => (x < 3 ? 0 : (x * (x - 1) * (x - 2)) / 6);

  const triples =
    comb3(c0) + // 0+0+0
    comb3(c1) + // 1+1+1
    comb3(c2) + // 2+2+2
    c0 * c1 * c2; // 0+1+2

  return triples;
};
