/**
 * Returns an array of planet names that lie between `planet1` and `planet2`
 * in the order of increasing distance from the Sun.
 *
 * @param {string} planet1 - The first planet name.
 * @param {string} planet2 - The second planet name.
 * @returns {string[]} An array of planet names between the two inputs.
 *                     Returns an empty array if either name is invalid
 *                     or if both names are the same.
 */
const bf = (planet1, planet2) => {
  const planets = [
    'Mercury',
    'Venus',
    'Earth',
    'Mars',
    'Jupiter',
    'Saturn',
    'Uranus',
    'Neptune',
  ];

  const idx1 = planets.indexOf(planet1);
  const idx2 = planets.indexOf(planet2);

  // Invalid planet names or identical planets → empty result
  if (idx1 === -1 || idx2 === -1 || idx1 === idx2) return [];

  // Ensure idx1 < idx2 for slicing
  const [start, end] = idx1 < idx2 ? [idx1, idx2] : [idx2, idx1];

  // Return planets strictly between the two indices
  return planets.slice(start + 1, end);
};
