/**
 * Counts how many numbers in the array are greater than 10
 * and have both their first and last digits odd (1,3,5,7,9).
 *
 * @param {number[]} nums - Array of numbers to evaluate.
 * @returns {number} The count of numbers satisfying the conditions.
 */
const specialFilter = (nums) => {
  let count = 0;

  for (const num of nums) {
    // Only consider numbers strictly greater than 10
    if (num <= 10) continue;

    // Work with the absolute value to ignore a leading minus sign
    const str = Math.abs(num).toString();

    // Extract first and last characters
    const firstDigit = parseInt(str[0], 10);
    const lastDigit = parseInt(str[str.length - 1], 10);

    // Check that both digits are odd
    if (firstDigit % 2 === 1 && lastDigit % 2 === 1) {
      count++;
    }
  }

  return count;
};
```

