/**
 * Returns a new list containing only the strings with even lengths,
 * sorted first by ascending length and then alphabetically for ties.
 *
 * @param {string[]} lst - The input list of strings.
 * @returns {string[]} A sorted list of strings with even lengths.
 */
const sortedListSum = (lst) => {
  // Keep only strings with even length
  const evenStrings = lst.filter(str => str.length % 2 === 0);

  // Sort by length, then alphabetically
  evenStrings.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length; // ascending length
    }
    return a.localeCompare(b); // alphabetical for same length
  });

  return evenStrings;
};
```

