// Helper to determine if a number is prime
const isPrime = (n) => {
  if (n <= 1) return false;          // 0, 1 and negative numbers are not prime
  if (n <= 3) return true;           // 2 and 3 are prime
  if (n % 2 === 0 || n % 3 === 0) return false;

  // Check divisibility by numbers of the form 6k ± 1
  for (let i = 5; i * i <= n; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) return false;
  }
  return true;
};

// Main function: return x if n is prime, otherwise y
const xOrY = (n, x, y) => (isPrime(n) ? x : y);
```

