/**
 * Counts the number of triples (i, j, k) with 1 ≤ i < j < k ≤ n
 * such that a[i] + a[j] + a[k] is divisible by 3,
 * where a[i] = i*i - i + 1.
 *
 * @param {number} n - The length of the array.
 * @returns {number} The number of valid triples.
 */
const getMaxTriples = (n) => {
  if (n < 3) return 0;

  // Count indices i where i % 3 === 2 (a[i] % 3 === 0)
  const count0 = Math.floor((n + 1) / 3);
  // Remaining indices have a[i] % 3 === 1
  const count1 = n - count0;

  const comb3 = (x) => (x < 3 ? 0 : (x * (x - 1) * (x - 2)) / 6);

  return comb3(count0) + comb3(count1);
};
