/**
 * Returns an array containing the absolute difference between each
 * corresponding element of `game` and `guess`.  If the values are equal
 * the difference is 0.
 *
 * @param {number[]} game  - Array of actual scores.
 * @param {number[]} guess - Array of guessed scores.
 * @returns {number[]} Array of absolute differences.
 */
const compare = (game, guess) => {
  const len = Math.min(game.length, guess.length);
  const result = new Array(len);

  for (let i = 0; i < len; i++) {
    result[i] = Math.abs(game[i] - guess[i]);
  }

  return result;
};
