/**
 * Compare two arrays of scores and guesses.
 *
 * @param {number[]} game  - The actual scores.
 * @param {number[]} guess - The guessed scores.
 * @returns {number[]} An array where each element is 0 if the guess matches the score,
 *                     otherwise the absolute difference between the guess and the score.
 */
const compare = (game, guess) => {
  if (!Array.isArray(game) || !Array.isArray(guess) || game.length !== guess.length) {
    throw new Error('Both arguments must be arrays of the same length.');
  }

  return game.map((score, i) => Math.abs(score - guess[i]));
};
