/**
 * Returns the class name concatenated with the strongest extension.
 *
 * @param {string} class_name - The base class name.
 * @param {string[]} extensions - Array of extension names.
 * @returns {string} The combined string in the format "ClassName.ExtensionName".
 */
const strongestExtension = (class_name, extensions) => {
  let bestIndex = 0;
  let bestStrength = -Infinity;

  for (let i = 0; i < extensions.length; i++) {
    const ext = extensions[i];
    let strength = 0;

    for (let j = 0; j < ext.length; j++) {
      const code = ext.charCodeAt(j);
      if (code >= 65 && code <= 90) {          // 'A' - 'Z'
        strength += 1;
      } else if (code >= 97 && code <= 122) {   // 'a' - 'z'
        strength -= 1;
      }
    }

    if (strength > bestStrength) {
      bestStrength = strength;
      bestIndex = i;
    }
  }

  return `${class_name}.${extensions[bestIndex]}`;
};
```

