/**
 * Returns true if any rotation of string `b` is a substring of string `a`.
 *
 * @param {string} a - The string to search within.
 * @param {string} b - The string whose rotations are to be checked.
 * @returns {boolean}
 */
const cycpatternCheck = (a, b) => {
  // An empty pattern is trivially found.
  if (b.length === 0) return true;

  // Concatenate the pattern with itself; every rotation of `b`
  // appears as a contiguous substring of this doubled string.
  const doubled = b + b;

  // Check each rotation.
  for (let i = 0; i < b.length; i++) {
    const rotation = doubled.slice(i, i + b.length);
    if (a.includes(rotation)) return true;
  }

  return false;
};
