/**
 * Counts the number of even and odd digits in an integer.
 *
 * @param {number} num - The integer to analyze.
 * @returns {[number, number]} A tuple where the first element is the count of even digits
 *                            and the second element is the count of odd digits.
 */
const evenOddCount = (num) => {
  // Convert to absolute value to ignore the sign
  const str = Math.abs(num).toString();

  let evenCount = 0;
  let oddCount = 0;

  for (const ch of str) {
    const digit = ch.charCodeAt(0) - 48; // '0' -> 48
    if (digit % 2 === 0) {
      evenCount++;
    } else {
      oddCount++;
    }
  }

  return [evenCount, oddCount];
};
