/**
 * Counts the number of even and odd digits in an integer.
 *
 * @param {number} num - The integer to analyze.
 * @returns {[number, number]} A tuple [evenCount, oddCount].
 */
const evenOddCount = (num) => {
  // Work with the absolute value to ignore the sign.
  let n = Math.abs(num);

  let evenCount = 0;
  let oddCount = 0;

  // Special case: 0 has one even digit.
  if (n === 0) {
    evenCount = 1;
  } else {
    while (n > 0) {
      const digit = n % 10;
      if (digit % 2 === 0) {
        evenCount++;
      } else {
        oddCount++;
      }
      n = Math.floor(n / 10);
    }
  }

  return [evenCount, oddCount];
};
