/**
 * Convert a positive integer (1 ≤ number ≤ 1000) to its Roman numeral representation
 * in lowercase.
 *
 * @param {number} number - The integer to convert.
 * @returns {string} The Roman numeral string.
 */
const intToMiniRoman = (number) => {
  if (number < 1 || number > 1000) {
    throw new RangeError('Number must be between 1 and 1000 inclusive.');
  }

  const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  const symbols = ['m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'];

  let result = '';
  for (let i = 0; i < values.length; i++) {
    while (number >= values[i]) {
      result += symbols[i];
      number -= values[i];
    }
  }
  return result;
};
