  while (number > 0) {
    const count = Math.floor(number / values[idx]); // how many times the current value fits
    number %= values[idx]; // remainder after using this value

    // Append the corresponding symbol 'count' times
    for (let j = 0; j < count; j++) {
      result += symbols[idx];
    }

    idx--; // move to the next smaller value
  }

  return result;
};
