/**
 * Determines whether three side lengths can form a right‑angled triangle.
 *
 * @param {number} a - Length of side a.
 * @param {number} b - Length of side b.
 * @param {number} c - Length of side c.
 * @returns {boolean} True if the sides form a right‑angled triangle, otherwise false.
 */
const rightAngleTriangle = (a, b, c) => {
  // Sort the sides so that z is the largest side (potential hypotenuse)
  const [x, y, z] = [a, b, c].sort((p, q) => p - q);

  // A triangle must satisfy the triangle inequality
  if (x + y <= z) return false;

  // Use a tolerance for floating‑point comparisons
  const EPS = 1e-10;
  return Math.abs(x * x + y * y - z * z) < EPS;
};
```

