/**
 * Returns an array where each element is the absolute difference between
 * the corresponding elements of `game` and `guess`. If the values are equal,
 * the result is 0.
 *
 * @param {number[]} game  - Array of actual scores.
 * @param {number[]} guess - Array of guessed scores.
 * @returns {number[]} Array of absolute differences.
 */
const compare = (game, guess) => {
  // Ensure both arrays have the same length; if not, compare up to the shorter length.
  const len = Math.min(game.length, guess.length);
  const result = new Array(len);

  for (let i = 0; i < len; i++) {
    result[i] = Math.abs(game[i] - guess[i]);
  }

  return result;
};
