const rightAngleTriangle = (a, b, c) => {
  // All sides must be positive numbers
  if (a <= 0 || b <= 0 || c <= 0) return false;

  // Sort the sides so that the largest is the potential hypotenuse
  const sides = [a, b, c].sort((x, y) => x - y);
  const [x, y, z] = sides; // x <= y <= z

  // Triangle inequality: sum of two smaller sides must be greater than the largest
  if (x + y <= z) return false;

  // Check the Pythagorean theorem
  // Use a small epsilon to account for floating‑point inaccuracies
  const epsilon = 1e-10;
  return Math.abs(x * x + y * y - z * z) < epsilon;
};
