/**
 * Returns the word with the maximum number of unique characters.
 * If multiple words tie, returns the lexicographically smallest one.
 *
 * @param {string[]} words - Array of words to evaluate.
 * @returns {string} The selected word, or an empty string if the input is empty.
 */
const findMax = (words) => {
  if (!Array.isArray(words) || words.length === 0) return '';

  let bestWord = '';
  let bestCount = -1;

  for (const word of words) {
    // Count unique characters using a Set
    const uniqueCount = new Set(word).size;

    if (
      uniqueCount > bestCount ||
      (uniqueCount === bestCount && word < bestWord)
    ) {
      bestCount = uniqueCount;
      bestWord = word;
    }
  }

  return bestWord;
};
```

