 * @param {number} a - Length of side a.
 * @param {number} b - Length of side b.
 * @param {number} c - Length of side c.
 * @returns {boolean} True if the sides form a right‑angled triangle, otherwise false.
 */
const rightAngleTriangle = (a, b, c) => {
  // Basic validation: all sides must be positive numbers
  if ([a, b, c].some((x) => typeof x !== 'number' || x <= 0)) {
    return false;
  }

  // Sort sides so that the largest is the potential hypotenuse
  const [x, y, z] = [a, b, c].sort((p, q) => p - q);

  // Use a tolerance to account for floating‑point arithmetic errors
  const tolerance = Number.EPSILON * Math.max(x * x + y * y, z * z);

  return Math.abs(x * x + y * y - z * z) <= tolerance;
};
