/**
 * Evaluate an algebraic expression defined by two parallel arrays:
 *   - operator: array of operators ('+', '-', '*', '//', '**')
 *   - operand:  array of non‑negative integers
 *
 * The operators are applied with the usual precedence:
 *   1. '**' (exponentiation)
 *   2. '*', '//' (multiplication and floor division)
 *   3. '+', '-' (addition and subtraction)
 *
 * @param {string[]} operator - list of operators
 * @param {number[]} operand  - list of operands
 * @returns {number} The result of evaluating the expression
 */
const doAlgebra = (operator, operand) => {
  // Work on copies so the original arrays are not mutated
  const ops = operator.slice();
  const nums = operand.slice();

  // Define precedence levels from highest to lowest
  const precedence = [
    ['**'],
    ['*', '//'],
    ['+', '-'],
  ];

  // Process each precedence level
  for (const level of precedence) {
    let i = 0;
    while (i < ops.length) {
      const op = ops[i];
      if (level.includes(op)) {
        const a = nums[i];
        const b = nums[i + 1];
        let result;

        switch (op) {
          case '**':
            result = Math.pow(a, b);
            break;
          case '*':
            result = a * b;
            break;
          case '//':
            // Floor division for non‑negative integers
            result = Math.floor(a / b);
            break;
          case '+':
            result = a + b;
            break;
          case '-':
            result = a - b;
            break;
          default:
            throw new Error(`Unsupported operator: ${op}`);
        }

        // Replace the two operands with the result and remove the operator
        nums.splice(i, 2, result);
        ops.splice(i, 1);
        // Stay at the same index to handle consecutive operators of the same precedence
      } else {
        i++;
      }
    }
  }

  // After all operations, the single remaining number is the result
  return nums[0];
};
