/**
 * Evaluate an algebraic expression defined by two parallel lists:
 *   - operator: array of binary operators ('+', '-', '*', '//', '**')
 *   - operand:  array of non‑negative integers
 *
 * The expression is evaluated following standard arithmetic precedence:
 *   1. '**' (right‑associative)
 *   2. '*', '//'
 *   3. '+', '-'
 *
 * @param {string[]} operator - list of operators
 * @param {number[]} operand  - list of operands
 * @returns {number} The evaluated result
 */
const doAlgebra = (operator, operand) => {
  // Helper: precedence of operators
  const precedence = (op) => {
    switch (op) {
      case '+':
      case '-':
        return 1;
      case '*':
      case '//':
        return 2;
      case '**':
        return 3;
      default:
        return 0;
    }
  };

  // Helper: associativity (true = left, false = right)
  const isLeftAssociative = (op) => op !== '**';

  // Shunting‑yard algorithm: convert to Reverse Polish Notation (RPN)
  const outputQueue = [];
  const operatorStack = [];

  for (let i = 0; i < operand.length; i++) {
    // Push current operand
    outputQueue.push(operand[i]);

    // If there's an operator after this operand, process it
    if (i < operator.length) {
      const op = operator[i];
      while (
        operatorStack.length &&
        precedence(operatorStack[operatorStack.length - 1]) > precedence(op) ||
        (precedence(operatorStack[operatorStack.length - 1]) === precedence(op) &&
          isLeftAssociative(op))
      ) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(op);
    }
  }

  // Pop any remaining operators
  while (operatorStack.length) {
    outputQueue.push(operatorStack.pop());
  }

  // Evaluate RPN
  const stack = [];
  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      let result;
      switch (token) {
        case '+':
          result = a + b;
          break;
        case '-':
          result = a - b;
          break;
        case '*':
          result = a * b;
          break;
        case '//':
          result = Math.floor(a / b);
          break;
        case '**':
          result = Math.pow(a, b);
          break;
        default:
          throw new Error(`Unsupported operator: ${token}`);
      }
      stack.push(result);
    }
  }

  return stack[0];
};
