/**
 * Evaluate an arithmetic expression given by two parallel arrays:
 *   operator: array of operators ('+', '-', '*', '//', '**')
 *   operand:  array of non‑negative integers
 *
 * The operators are applied with the usual precedence:
 *   1. '**'   (right‑associative)
 *   2. '*', '//'
 *   3. '+', '-'
 *
 * @param {string[]} operator - list of operators
 * @param {number[]} operand  - list of operands
 * @returns {number} The evaluated result
 */
const doAlgebra = (operator, operand) => {
  // Precedence table
  const precedence = {
    '**': 4,
    '*': 3,
    '//': 3,
    '+': 2,
    '-': 2,
  };

  // Right‑associative operators
  const rightAssociative = new Set(['**']);

  // Helper to apply an operator to two operands
  const applyOp = (op, b, a) => {
    switch (op) {
      case '+': return a + b;
      case '-': return a - b;
      case '*': return a * b;
      case '//': return Math.floor(a / b);
      case '**': return Math.pow(a, b);
      default: throw new Error(`Unsupported operator: ${op}`);
    }
  };

  const values = [];
  const ops = [];

  // Iterate over operands and operators
  for (let i = 0; i < operand.length; i++) {
    values.push(operand[i]);

    if (i < operator.length) {
      const currentOp = operator[i];

      // Resolve operators on the stack according to precedence
      while (ops.length > 0) {
        const topOp = ops[ops.length - 1];
        const topPrec = precedence[topOp];
        const curPrec = precedence[currentOp];

        const shouldPop =
          (!rightAssociative.has(currentOp) && topPrec >= curPrec) ||
          (rightAssociative.has(currentOp) && topPrec > curPrec);

        if (!shouldPop) break;

        ops.pop();
        const b = values.pop();
        const a = values.pop();
        values.push(applyOp(topOp, b, a));
      }

      ops.push(currentOp);
    }
  }

  // Apply remaining operators
  while (ops.length > 0) {
    const op = ops.pop();
    const b = values.pop();
    const a = values.pop();
    values.push(applyOp(op, b, a));
  }

  return values[0];
};
