const solve = (s) => {
  let hasLetter = false;
  let result = '';

  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);

    if (code >= 65 && code <= 90) {          // 'A'–'Z'
      hasLetter = true;
      result += String.fromCharCode(code + 32); // to lowercase
    } else if (code >= 97 && code <= 122) {   // 'a'–'z'
      hasLetter = true;
      result += String.fromCharCode(code - 32); // to uppercase
    } else {
      result += s[i]; // non‑letter stays unchanged
    }
  }

  return hasLetter ? result : s.split('').reverse().join('');
};
