/**
 * Returns true if the product of two fractions is an integer.
 *
 * @param {string} x - First fraction in the form "numerator/denominator".
 * @param {string} n - Second fraction in the form "numerator/denominator".
 * @returns {boolean} True if the product is a whole number, false otherwise.
 */
const simplify = (x, n) => {
  // Helper to parse a fraction string into BigInt numerator and denominator
  const parseFraction = (frac) => {
    const [numStr, denStr] = frac.split('/');
    return [BigInt(numStr), BigInt(denStr)];
  };

  const [numX, denX] = parseFraction(x);
  const [numN, denN] = parseFraction(n);

  // Compute the product numerator and denominator
  const productNum = numX * numN;
  const productDen = denX * denN;

  // The product is an integer iff the denominator divides the numerator
  return productNum % productDen === 0n;
};
