/**
 * Returns all even single‑digit numbers between a and b (inclusive),
 * sorted in ascending order.
 *
 * @param {number} a - First positive integer.
 * @param {number} b - Second positive integer.
 * @returns {number[]} Array of even digits between a and b.
 */
const generateIntegers = (a, b) => {
  // Ensure a is the smaller value
  const [start, end] = a <= b ? [a, b] : [b, a];

  const result = [];
  // Only single‑digit numbers are relevant (0–9)
  const upperLimit = Math.min(end, 9);

  for (let i = start; i <= upperLimit; i++) {
    if (i % 2 === 0) {
      result.push(i);
    }
  }

  return result;
};
