/**
 * Returns the even digits (2, 4, 6, 8) that lie between the two given
 * positive integers a and b, inclusive, in ascending order.
 *
 * @param {number} a - First positive integer.
 * @param {number} b - Second positive integer.
 * @returns {number[]} Array of even digits between a and b.
 */
const generateIntegers = (a, b) => {
  const start = Math.min(a, b);
  const end   = Math.max(a, b);
  const result = [];

  for (let i = start; i <= end; i++) {
    if (i % 2 === 0 && i >= 2 && i <= 8) {
      result.push(i);
    }
  }

  return result;
};
