const solve = (s) => {
  let hasLetter = false;
  let transformed = '';

  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);

    if (code >= 65 && code <= 90) {          // 'A'–'Z'
      transformed += String.fromCharCode(code + 32); // to lowercase
      hasLetter = true;
    } else if (code >= 97 && code <= 122) {   // 'a'–'z'
      transformed += String.fromCharCode(code - 32); // to uppercase
      hasLetter = true;
    } else {
      transformed += s[i];
    }
  }

  if (!hasLetter) {
    // reverse the string if no letters were found
    return transformed.split('').reverse().join('');
  }

  return transformed;
};
